enum class SourceProcessKind {
    kSkipped,
    kInvalid,
    kBudgetExceeded,
    kCopied,
    kDecompiled,
    kNonexact,
    kDisassembled,
    kFailed,
};

bool IsUsableLuaProcessKind(SourceProcessKind kind) {
    return kind == SourceProcessKind::kCopied ||
           kind == SourceProcessKind::kDecompiled ||
           kind == SourceProcessKind::kNonexact;
}

bool IsTerminalFallbackProcessKind(SourceProcessKind kind) {
    return kind == SourceProcessKind::kFailed ||
           kind == SourceProcessKind::kDisassembled ||
           kind == SourceProcessKind::kInvalid ||
           kind == SourceProcessKind::kBudgetExceeded;
}

bool TryUnwrapRawTopLevelVarargFunction(std::string& source) {
    constexpr std::string_view kPrefix = "function(...)\n";
    if (!internal::StartsWith(source, kPrefix)) {
        return false;
    }
    std::size_t end_pos = source.size();
    while (end_pos > kPrefix.size() &&
           (source[end_pos - 1] == '\n' || source[end_pos - 1] == '\r' ||
            source[end_pos - 1] == ' ' || source[end_pos - 1] == '\t')) {
        --end_pos;
    }
    constexpr std::string_view kSuffix = "end";
    if (end_pos < kPrefix.size() + kSuffix.size() ||
        source.compare(end_pos - kSuffix.size(), kSuffix.size(), kSuffix) != 0) {
        return false;
    }
    source = source.substr(kPrefix.size(), end_pos - kPrefix.size() - kSuffix.size());
    if (source.empty() || source.back() != '\n') {
        source.push_back('\n');
    }
    return true;
}

bool TryRewriteWorkspaceInlineTableFieldAssignments(std::string& source,
                                                    std::string* note,
                                                    std::string_view note_prefix) {
    internal::LuaMutableTextContext text_context(source);
    const std::vector<std::string>& lines = text_context.EnsureLines();
    std::vector<std::string> rewritten_lines;
    rewritten_lines.reserve(lines.size() + 8);
    bool changed = false;
    int rewrite_index = 0;

    for (const std::string& line : lines) {
        const std::string_view trimmed =
            internal::TrimWhitespace(internal::StripLineComment(line));
        const std::size_t assignment_pos = trimmed.rfind(" = ");
        if (assignment_pos == std::string_view::npos || assignment_pos == 0 ||
            assignment_pos + 3 >= trimmed.size()) {
            rewritten_lines.push_back(line);
            continue;
        }

        const std::string_view lhs =
            internal::TrimWhitespace(trimmed.substr(0, assignment_pos));
        const std::string_view rhs =
            internal::TrimWhitespace(trimmed.substr(assignment_pos + 3));
        if (lhs.empty() || rhs.empty()) {
            rewritten_lines.push_back(line);
            continue;
        }

        const std::size_t dot_suffix_pos = lhs.find("}.");
        const std::size_t bracket_suffix_pos = lhs.find("}[");
        const std::size_t suffix_pos =
            dot_suffix_pos == std::string_view::npos
                ? bracket_suffix_pos
                : (bracket_suffix_pos == std::string_view::npos
                       ? dot_suffix_pos
                       : std::min(dot_suffix_pos, bracket_suffix_pos));
        if (suffix_pos == std::string_view::npos) {
            rewritten_lines.push_back(line);
            continue;
        }

        const std::size_t table_expr_end = suffix_pos + 1;
        const std::string_view table_expr = lhs.substr(0, table_expr_end);
        const std::string_view field_suffix = lhs.substr(table_expr_end);
        if (table_expr.size() < 2 || table_expr.front() != '{' ||
            table_expr.back() != '}') {
            rewritten_lines.push_back(line);
            continue;
        }

        const std::size_t indent_end = line.find_first_not_of(" \t");
        const std::string indent =
            indent_end == std::string::npos ? std::string() : line.substr(0, indent_end);
        const std::string temp_name =
            "__refii_readable_table_" + std::to_string(++rewrite_index);
        rewritten_lines.push_back(indent + "local " + temp_name + " = " +
                                  std::string(table_expr));
        rewritten_lines.push_back(indent + temp_name + std::string(field_suffix) + " = " +
                                  std::string(rhs));
        changed = true;
    }

    if (!changed) {
        return false;
    }

    text_context.SetLines(std::move(rewritten_lines), text_context.HadTrailingNewline());
    source = std::string(text_context.EnsureSource());
    if (note != nullptr) {
        *note = internal::JoinNotes(
            *note,
            std::string(note_prefix) +
                "_syntax_repair_inline_table_assignment_normalized");
    }
    return true;
}

bool TryNormalizeWorkspaceNumericCallPrefixes(std::string& source,
                                              std::string* note,
                                              std::string_view note_prefix) {
    internal::LuaMutableTextContext text_context(source);
    std::vector<std::string>* lines = text_context.EnsureMutableLines();
    bool changed_any = false;

    for (std::string& line : *lines) {
        std::string rewritten;
        rewritten.reserve(line.size());
        bool line_changed = false;
        for (std::size_t index = 0; index < line.size(); ++index) {
            const char ch = line[index];
            if (ch >= '0' && ch <= '9') {
                std::size_t digit_end = index;
                while (digit_end < line.size() && line[digit_end] >= '0' &&
                       line[digit_end] <= '9') {
                    ++digit_end;
                }
                if (digit_end < line.size() && line[digit_end] == '(') {
                    const bool at_identifier_tail =
                        index > 0 &&
                        (std::isalnum(static_cast<unsigned char>(line[index - 1])) != 0 ||
                         line[index - 1] == '_');
                    if (!at_identifier_tail) {
                        line_changed = true;
                        index = digit_end - 1;
                        continue;
                    }
                }
            }
            rewritten.push_back(ch);
        }
        if (line_changed) {
            line = std::move(rewritten);
            changed_any = true;
        }
    }

    if (!changed_any) {
        return false;
    }

    text_context.MarkLinesMutated();
    source = std::string(text_context.EnsureSource());
    if (note != nullptr) {
        *note = internal::JoinNotes(
            *note,
            std::string(note_prefix) +
                "_syntax_repair_numeric_call_prefix_normalized");
    }
    return true;
}

bool TryNormalizeWorkspaceParenthesizedTuples(std::string& source,
                                              std::string* note,
                                              std::string_view note_prefix) {
    internal::LuaMutableTextContext text_context(source);
    std::vector<std::string>* lines = text_context.EnsureMutableLines();
    bool changed_any = false;

    for (std::string& line : *lines) {
        std::size_t search_from = 0;
        while (search_from < line.size()) {
            const std::size_t open = line.find("((", search_from);
            if (open == std::string::npos) {
                break;
            }
            if (open > 0) {
                const unsigned char previous =
                    static_cast<unsigned char>(line[open - 1]);
                if (std::isalnum(previous) != 0 || line[open - 1] == '_' ||
                    line[open - 1] == ')' || line[open - 1] == ']' ||
                    line[open - 1] == '[') {
                    search_from = open + 2;
                    continue;
                }
            }
            const std::size_t close = line.find("))", open + 2);
            if (close == std::string::npos) {
                break;
            }
            const std::string_view inner(line.data() + open + 2, close - (open + 2));
            const std::size_t comma = inner.find(',');
            if (comma == std::string_view::npos) {
                search_from = close + 2;
                continue;
            }
            const std::string_view first_value =
                internal::TrimWhitespace(inner.substr(0, comma));
            if (first_value.empty()) {
                search_from = close + 2;
                continue;
            }
            const std::string replacement = "((" + std::string(first_value) + "))";
            line.replace(open, close - open + 2, replacement);
            search_from = open + replacement.size();
            changed_any = true;
        }
    }

    if (!changed_any) {
        return false;
    }

    text_context.MarkLinesMutated();
    source = std::string(text_context.EnsureSource());
    if (note != nullptr) {
        *note = internal::JoinNotes(
            *note,
            std::string(note_prefix) +
                "_syntax_repair_parenthesized_tuple_normalized");
    }
    return true;
}

bool TryBalanceWorkspaceTrailingAssignmentParentheses(std::string& source,
                                                      std::string* note,
                                                      std::string_view note_prefix) {
    internal::LuaMutableTextContext text_context(source);
    std::vector<std::string>* lines = text_context.EnsureMutableLines();
    bool changed_any = false;

    const auto line_paren_delta = [](std::string_view text) {
        int delta = 0;
        bool in_single_quote = false;
        bool in_double_quote = false;
        bool escaped = false;
        for (char ch : text) {
            if (escaped) {
                escaped = false;
                continue;
            }
            if ((in_single_quote || in_double_quote) && ch == '\\') {
                escaped = true;
                continue;
            }
            if (!in_double_quote && ch == '\'') {
                in_single_quote = !in_single_quote;
                continue;
            }
            if (!in_single_quote && ch == '"') {
                in_double_quote = !in_double_quote;
                continue;
            }
            if (in_single_quote || in_double_quote) {
                continue;
            }
            if (ch == '(') {
                ++delta;
            } else if (ch == ')') {
                --delta;
            }
        }
        return delta;
    };

    for (std::size_t index = 0; index < lines->size(); ++index) {
        const std::string_view stripped = internal::StripLineComment((*lines)[index]);
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        if (trimmed.empty() || trimmed.find('=') == std::string_view::npos) {
            continue;
        }
        const int delta = line_paren_delta(stripped);
        if (delta <= 0) {
            continue;
        }

        std::size_t next = index + 1;
        while (next < lines->size()) {
            const std::string_view next_trimmed =
                internal::TrimWhitespace(internal::StripLineComment((*lines)[next]));
            if (next_trimmed.empty()) {
                ++next;
                continue;
            }
            const bool looks_like_next_statement =
                next_trimmed.find('=') != std::string_view::npos ||
                internal::StartsWith(next_trimmed, "if ") ||
                internal::StartsWith(next_trimmed, "while ") ||
                internal::StartsWith(next_trimmed, "for ") ||
                next_trimmed == "end";
            if (!looks_like_next_statement) {
                break;
            }
            (*lines)[index].append(static_cast<std::size_t>(delta), ')');
            changed_any = true;
            break;
        }
    }

    if (!changed_any) {
        return false;
    }

    text_context.MarkLinesMutated();
    source = std::string(text_context.EnsureSource());
    if (note != nullptr) {
        *note = internal::JoinNotes(
            *note,
            std::string(note_prefix) +
                "_syntax_repair_assignment_paren_balance_normalized");
    }
    return true;
}

bool TryBalanceWorkspaceMissingBracketAssignmentLhs(std::string& source,
                                                    std::string* note,
                                                    std::string_view note_prefix) {
    internal::LuaMutableTextContext text_context(source);
    std::vector<std::string>* lines = text_context.EnsureMutableLines();
    bool changed_any = false;

    const auto find_assignment_equals = [](std::string_view text) -> std::size_t {
        bool in_single_quote = false;
        bool in_double_quote = false;
        bool escaped = false;
        for (std::size_t index = 0; index < text.size(); ++index) {
            const char ch = text[index];
            if (escaped) {
                escaped = false;
                continue;
            }
            if ((in_single_quote || in_double_quote) && ch == '\\') {
                escaped = true;
                continue;
            }
            if (!in_double_quote && ch == '\'') {
                in_single_quote = !in_single_quote;
                continue;
            }
            if (!in_single_quote && ch == '"') {
                in_double_quote = !in_double_quote;
                continue;
            }
            if (in_single_quote || in_double_quote || ch != '=') {
                continue;
            }
            if ((index > 0 && (text[index - 1] == '~' || text[index - 1] == '<' ||
                               text[index - 1] == '>' || text[index - 1] == '=')) ||
                (index + 1 < text.size() && text[index + 1] == '=')) {
                continue;
            }
            return index;
        }
        return std::string_view::npos;
    };

    const auto bracket_delta = [](std::string_view text) {
        int delta = 0;
        bool in_single_quote = false;
        bool in_double_quote = false;
        bool escaped = false;
        for (char ch : text) {
            if (escaped) {
                escaped = false;
                continue;
            }
            if ((in_single_quote || in_double_quote) && ch == '\\') {
                escaped = true;
                continue;
            }
            if (!in_double_quote && ch == '\'') {
                in_single_quote = !in_single_quote;
                continue;
            }
            if (!in_single_quote && ch == '"') {
                in_double_quote = !in_double_quote;
                continue;
            }
            if (in_single_quote || in_double_quote) {
                continue;
            }
            if (ch == '[') {
                ++delta;
            } else if (ch == ']' && delta > 0) {
                --delta;
            }
        }
        return delta;
    };

    for (std::string& line : *lines) {
        const std::size_t indent_end = line.find_first_not_of(" \t");
        const std::string indent =
            indent_end == std::string::npos ? std::string() : line.substr(0, indent_end);
        const std::string_view body =
            indent_end == std::string::npos ? std::string_view() : std::string_view(line).substr(indent_end);
        const std::string_view stripped = internal::StripLineComment(body);
        const std::size_t equals = find_assignment_equals(stripped);
        if (equals == std::string_view::npos || equals == 0) {
            continue;
        }

        const std::string_view lhs = internal::TrimWhitespace(stripped.substr(0, equals));
        const std::string_view rhs = internal::TrimWhitespace(stripped.substr(equals + 1));
        const int missing_brackets = bracket_delta(lhs);
        if (missing_brackets <= 0 || lhs.find('[') == std::string_view::npos ||
            rhs.empty()) {
            continue;
        }

        line = indent + std::string(lhs) +
               std::string(static_cast<std::size_t>(missing_brackets), ']') +
               " = " + std::string(rhs);
        changed_any = true;
    }

    if (!changed_any) {
        return false;
    }

    text_context.MarkLinesMutated();
    source = std::string(text_context.EnsureSource());
    if (note != nullptr) {
        *note = internal::JoinNotes(
            *note,
            std::string(note_prefix) +
                "_syntax_repair_missing_bracket_assignment_lhs_normalized");
    }
    return true;
}

bool TryNormalizeWorkspaceMalformedCallResultAssignments(std::string& source,
                                                         std::string* note,
                                                         std::string_view note_prefix) {
    internal::LuaMutableTextContext text_context(source);
    std::vector<std::string>* lines = text_context.EnsureMutableLines();
    bool changed_any = false;

    const auto find_top_level_comma = [](std::string_view value) -> std::size_t {
        int paren_depth = 0;
        int bracket_depth = 0;
        int brace_depth = 0;
        bool in_single_quote = false;
        bool in_double_quote = false;
        bool escaped = false;
        for (std::size_t index = 0; index < value.size(); ++index) {
            const char ch = value[index];
            if (escaped) {
                escaped = false;
                continue;
            }
            if ((in_single_quote || in_double_quote) && ch == '\\') {
                escaped = true;
                continue;
            }
            if (!in_double_quote && ch == '\'') {
                in_single_quote = !in_single_quote;
                continue;
            }
            if (!in_single_quote && ch == '"') {
                in_double_quote = !in_double_quote;
                continue;
            }
            if (in_single_quote || in_double_quote) {
                continue;
            }
            switch (ch) {
            case '(':
                ++paren_depth;
                break;
            case ')':
                if (paren_depth > 0) {
                    --paren_depth;
                }
                break;
            case '[':
                ++bracket_depth;
                break;
            case ']':
                if (bracket_depth > 0) {
                    --bracket_depth;
                }
                break;
            case '{':
                ++brace_depth;
                break;
            case '}':
                if (brace_depth > 0) {
                    --brace_depth;
                }
                break;
            case ',':
                if (paren_depth == 0 && bracket_depth == 0 && brace_depth == 0) {
                    return index;
                }
                break;
            default:
                break;
            }
        }
        return std::string_view::npos;
    };

    const auto split_top_level_commas = [&](std::string_view value) {
        std::vector<std::string> parts;
        std::size_t start = 0;
        while (start <= value.size()) {
            const std::size_t comma = find_top_level_comma(value.substr(start));
            if (comma == std::string_view::npos) {
                parts.push_back(
                    std::string(internal::TrimWhitespace(value.substr(start))));
                break;
            }
            parts.push_back(std::string(
                internal::TrimWhitespace(value.substr(start, comma))));
            start += comma + 1;
        }
        return parts;
    };

    const auto is_assignable_lhs = [](std::string_view lhs) {
        lhs = internal::TrimWhitespace(lhs);
        if (lhs.empty() || lhs.find('(') != std::string_view::npos ||
            lhs.find(')') != std::string_view::npos) {
            return false;
        }
        if (refii::lua::IsValidLuaIdentifier(lhs) && !refii::lua::IsLuaKeyword(lhs)) {
            return true;
        }
        bool saw_field_or_index = false;
        int bracket_depth = 0;
        for (std::size_t index = 0; index < lhs.size(); ++index) {
            const char ch = lhs[index];
            if (std::isalnum(static_cast<unsigned char>(ch)) != 0 || ch == '_' ||
                ch == '.' || ch == ':' || ch == '"' || ch == '\'' || ch == ' ' ||
                ch == '\t') {
                if (ch == '.' || ch == ':') {
                    saw_field_or_index = true;
                }
                continue;
            }
            if (ch == '[') {
                ++bracket_depth;
                saw_field_or_index = true;
                continue;
            }
            if (ch == ']') {
                if (bracket_depth == 0) {
                    return false;
                }
                --bracket_depth;
                continue;
            }
            return false;
        }
        return saw_field_or_index && bracket_depth == 0;
    };

    for (std::string& line : *lines) {
        const std::string_view stripped = internal::StripLineComment(line);
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        const std::size_t equals_pos = trimmed.find('=');
        if (trimmed.empty() || equals_pos == std::string_view::npos) {
            continue;
        }

        const std::string_view lhs = internal::TrimWhitespace(trimmed.substr(0, equals_pos));
        const std::string_view rhs = trimmed.substr(equals_pos + 1);
        const std::size_t comma_pos = find_top_level_comma(lhs);
        if (comma_pos == std::string_view::npos) {
            continue;
        }

        std::vector<std::string> lhs_parts = split_top_level_commas(lhs);
        bool line_changed = false;
        for (std::string& lhs_part : lhs_parts) {
            if (is_assignable_lhs(lhs_part)) {
                continue;
            }
            if (lhs_part.find('(') == std::string::npos ||
                lhs_part.find(')') == std::string::npos) {
                continue;
            }
            lhs_part = "_";
            line_changed = true;
        }
        if (!line_changed) {
            continue;
        }

        const std::size_t indent_end = line.find_first_not_of(" \t");
        const std::string indent =
            indent_end == std::string::npos ? std::string() : line.substr(0, indent_end);
        std::string rewritten_lhs;
        for (std::size_t part_index = 0; part_index < lhs_parts.size(); ++part_index) {
            if (part_index != 0) {
                rewritten_lhs += ", ";
            }
            rewritten_lhs += lhs_parts[part_index];
        }
        line = indent + rewritten_lhs + " =" + std::string(rhs);
        changed_any = true;
    }

    if (!changed_any) {
        return false;
    }

    text_context.MarkLinesMutated();
    source = std::string(text_context.EnsureSource());
    if (note != nullptr) {
        *note = internal::JoinNotes(
            *note,
            std::string(note_prefix) +
                "_syntax_repair_malformed_call_result_assignment_normalized");
    }
    return true;
}

std::string RepairWorkspaceReadableRecoverySyntax(
    std::string& source,
    const std::filesystem::path& relative_input,
    std::string* note,
    std::string_view note_prefix) {
    const std::string validation_label = relative_input.generic_string();
    std::string validation_error =
        internal::ValidateLuaSource(source, validation_label);
    if (validation_error.empty()) {
        return {};
    }

    constexpr int kMaxReadableRecoverySyntaxRepairPasses = 3;
    for (int pass = 0; pass < kMaxReadableRecoverySyntaxRepairPasses &&
                       !validation_error.empty();
         ++pass) {
        bool changed = false;
        if (validation_error.find("unexpected symbol near '='") != std::string::npos ||
            validation_error.find("unexpected symbol near '{'") != std::string::npos) {
            changed |= TryRewriteWorkspaceInlineTableFieldAssignments(
                source, note, note_prefix);
        }
        if (validation_error.find("']' expected near '='") != std::string::npos ||
            validation_error.find("']' expected near '=") != std::string::npos) {
            changed |= TryBalanceWorkspaceMissingBracketAssignmentLhs(
                source, note, note_prefix);
        }
        if (validation_error.find("')' expected near '('") != std::string::npos ||
            validation_error.find("unexpected symbol near '('") != std::string::npos) {
            changed |= TryNormalizeWorkspaceNumericCallPrefixes(source, note, note_prefix);
            changed |=
                TryNormalizeWorkspaceMalformedCallResultAssignments(source, note, note_prefix);
        }
        if (validation_error.find("')' expected near ','") != std::string::npos ||
            validation_error.find("unexpected symbol near ','") != std::string::npos ||
            validation_error.find("syntax error near '='") != std::string::npos) {
            changed |= TryNormalizeWorkspaceParenthesizedTuples(source, note, note_prefix);
            changed |=
                TryNormalizeWorkspaceMalformedCallResultAssignments(source, note, note_prefix);
            changed |= TryBalanceWorkspaceTrailingAssignmentParentheses(
                source, note, note_prefix);
        }
        if (validation_error.find("')' expected (to close '(' at line") !=
            std::string::npos) {
            changed |= TryBalanceWorkspaceTrailingAssignmentParentheses(
                source, note, note_prefix);
        }

        if (!changed) {
            break;
        }
        validation_error = internal::ValidateLuaSource(source, validation_label);
        if (note != nullptr) {
            *note = internal::JoinNotes(
                *note,
                validation_error.empty()
                    ? std::string(note_prefix) + "_syntax_repair_validated"
                    : std::string(note_prefix) + "_syntax_repair_progress");
        }
    }

    return validation_error;
}

bool IsReadableRecoveryNonexactNote(std::string_view note) {
    return note.find("workspace_direct_readable_recovery_valid_nonexact") !=
               std::string_view::npos ||
           note.find("workspace_direct_readable_recovery_promoted_exact") !=
               std::string_view::npos;
}

bool IsPreservableReadableNonexactHoldoutNote(std::string_view note) {
    return IsReadableRecoveryNonexactNote(note) ||
           (note.find("quality_rejected_registerized_output=") != std::string_view::npos &&
            note.find("validated_nonexact") != std::string_view::npos);
}

bool ParseFastLuaAssignment(std::string_view line,
                            std::string* lhs_out,
                            std::string* rhs_out,
                            bool* is_local_out = nullptr) {
    if (lhs_out == nullptr || rhs_out == nullptr) {
        return false;
    }

    std::string_view trimmed =
        internal::TrimWhitespace(internal::StripLineComment(line));
    bool is_local = false;
    if (internal::StartsWith(trimmed, "local ")) {
        is_local = true;
        trimmed = internal::TrimWhitespace(trimmed.substr(6));
    }
    if (trimmed.empty() ||
        internal::StartsWith(trimmed, "if ") ||
        internal::StartsWith(trimmed, "while ") ||
        internal::StartsWith(trimmed, "for ") ||
        internal::StartsWith(trimmed, "function ") ||
        internal::StartsWith(trimmed, "return ")) {
        return false;
    }

    const std::size_t equals = trimmed.find('=');
    if (equals == std::string_view::npos ||
        (equals > 0 && (trimmed[equals - 1] == '~' ||
                        trimmed[equals - 1] == '<' ||
                        trimmed[equals - 1] == '>')) ||
        (equals + 1 < trimmed.size() && trimmed[equals + 1] == '=')) {
        return false;
    }

    std::string_view lhs = internal::TrimWhitespace(trimmed.substr(0, equals));
    std::string_view rhs = internal::TrimWhitespace(trimmed.substr(equals + 1));
    if (lhs.empty() || rhs.empty() || lhs.find(',') != std::string_view::npos) {
        return false;
    }

    *lhs_out = std::string(lhs);
    *rhs_out = std::string(rhs);
    if (is_local_out != nullptr) {
        *is_local_out = is_local;
    }
    return true;
}

bool IsSyntheticRegisterTempName(std::string_view name) {
    if (name.size() < 2 || name.front() != 'r') {
        return false;
    }
    for (std::size_t index = 1; index < name.size(); ++index) {
        if (!std::isdigit(static_cast<unsigned char>(name[index]))) {
            return false;
        }
    }
    return true;
}

bool IsFastGeneratedFunctionParameterName(std::string_view name) {
    if (name.size() < 4 || (name.front() != 'A' && name.front() != 'L')) {
        return false;
    }
    std::size_t cursor = 1;
    bool saw_first_digits = false;
    while (cursor < name.size() &&
           std::isdigit(static_cast<unsigned char>(name[cursor])) != 0) {
        saw_first_digits = true;
        ++cursor;
    }
    if (!saw_first_digits || cursor >= name.size() || name[cursor] != '_') {
        return false;
    }
    ++cursor;
    bool saw_second_digits = false;
    while (cursor < name.size() &&
           std::isdigit(static_cast<unsigned char>(name[cursor])) != 0) {
        saw_second_digits = true;
        ++cursor;
    }
    return saw_second_digits && cursor == name.size();
}

std::optional<std::size_t> FastGeneratedRegisterIndex(std::string_view name) {
    if (name.size() < 4 || (name.front() != 'A' && name.front() != 'L')) {
        return std::nullopt;
    }
    std::size_t cursor = 1;
    std::size_t value = 0;
    bool saw_digits = false;
    while (cursor < name.size() &&
           std::isdigit(static_cast<unsigned char>(name[cursor])) != 0) {
        saw_digits = true;
        value = (value * 10) + static_cast<std::size_t>(name[cursor] - '0');
        ++cursor;
    }
    if (!saw_digits || cursor >= name.size() || name[cursor] != '_') {
        return std::nullopt;
    }
    ++cursor;
    bool saw_suffix_digits = false;
    while (cursor < name.size() &&
           std::isdigit(static_cast<unsigned char>(name[cursor])) != 0) {
        saw_suffix_digits = true;
        ++cursor;
    }
    if (!saw_suffix_digits || cursor != name.size()) {
        return std::nullopt;
    }
    return value;
}

bool SplitFastTopLevelCommaArguments(std::string_view value,
                                     std::vector<std::string>* arguments_out);
bool FindFastLuaMatchingEnd(const std::vector<std::string>& lines,
                            std::size_t block_start,
                            std::size_t* block_end);

bool FindFastEnclosingFunctionRange(const std::vector<std::string>& lines,
                                    std::size_t line_index,
                                    std::size_t* function_start_out,
                                    std::size_t* function_end_out) {
    if (function_start_out == nullptr || function_end_out == nullptr ||
        line_index >= lines.size()) {
        return false;
    }
    for (std::size_t probe = line_index + 1; probe-- > 0;) {
        const std::string_view trimmed =
            internal::TrimWhitespace(internal::StripLineComment(lines[probe]));
        std::size_t function_end = 0;
        if (trimmed.find("function") != std::string_view::npos &&
            FindFastLuaMatchingEnd(lines, probe, &function_end) &&
            function_end >= line_index) {
            *function_start_out = probe;
            *function_end_out = function_end;
            return true;
        }
        if (probe == 0) {
            break;
        }
    }
    return false;
}

std::string FastNextGeneratedLocalName(const std::vector<std::string>& lines,
                                       std::size_t function_start,
                                       std::size_t function_end) {
    std::size_t max_index = 0;
    if (function_start < lines.size()) {
        const std::string_view header =
            internal::TrimWhitespace(internal::StripLineComment(lines[function_start]));
        const std::size_t open = header.find('(');
        const std::size_t close = header.find(')', open == std::string_view::npos
                                           ? 0
                                           : open + 1);
        if (open != std::string_view::npos && close != std::string_view::npos &&
            close > open) {
            std::vector<std::string> parameters;
            if (SplitFastTopLevelCommaArguments(header.substr(open + 1,
                                                              close - open - 1),
                                                &parameters)) {
                for (const std::string& parameter : parameters) {
                    if (const std::optional<std::size_t> index =
                            FastGeneratedRegisterIndex(
                                internal::TrimWhitespace(parameter))) {
                        max_index = std::max(max_index, *index);
                    }
                }
            }
        }
    }

    function_end = std::min(function_end, lines.empty() ? 0 : lines.size() - 1);
    for (std::size_t line_index = function_start; line_index <= function_end;
         ++line_index) {
        const std::string_view line = internal::StripLineComment(lines[line_index]);
        for (std::size_t cursor = 0; cursor < line.size(); ++cursor) {
            if (line[cursor] != 'L') {
                continue;
            }
            std::size_t end = cursor + 1;
            while (end < line.size() &&
                   (std::isalnum(static_cast<unsigned char>(line[end])) != 0 ||
                    line[end] == '_')) {
                ++end;
            }
            if (const std::optional<std::size_t> index =
                    FastGeneratedRegisterIndex(line.substr(cursor, end - cursor))) {
                max_index = std::max(max_index, *index);
            }
            cursor = end;
        }
    }

    const std::size_t next_index = max_index + 1;
    return "L" + std::to_string(next_index) + "_" + std::to_string(next_index);
}

bool IsFastSyntheticTempReferencedBeforeNextAssignment(
    const std::vector<std::string>& lines,
    std::size_t first_line,
    std::string_view temp_name) {
    for (std::size_t line_index = first_line; line_index < lines.size(); ++line_index) {
        std::string lhs;
        std::string rhs;
        bool is_local = false;
        if (ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) &&
            lhs == temp_name) {
            return false;
        }
        if (internal::ContainsIdentifierReference(
                internal::StripLineComment(lines[line_index]), temp_name)) {
            return true;
        }
    }
    return false;
}

bool CollapseFastBoundedHotspotSingleUseTemps(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;
    for (std::size_t line_index = 0; line_index + 1 < lines.size(); ++line_index) {
        std::string temp_name;
        std::string temp_rhs;
        bool is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index],
                                    &temp_name,
                                    &temp_rhs,
                                    &is_local) ||
            !IsSyntheticRegisterTempName(temp_name)) {
            continue;
        }

        std::string target_lhs;
        std::string target_rhs;
        bool target_is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index + 1],
                                    &target_lhs,
                                    &target_rhs,
                                    &target_is_local) ||
            target_is_local ||
            target_rhs != temp_name ||
            IsFastSyntheticTempReferencedBeforeNextAssignment(lines,
                                                              line_index + 2,
                                                              temp_name)) {
            continue;
        }

        lines[line_index] =
            internal::GetLuaLineIndent(lines[line_index]) + target_lhs + " = " + temp_rhs;
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(line_index + 1));
        changed = true;
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool FoldFastBoundedHotspotSingleUseIdentifierAliases(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;
    for (std::size_t line_index = 0; line_index + 1 < lines.size(); ++line_index) {
        std::string temp_name;
        std::string temp_rhs;
        bool is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index],
                                    &temp_name,
                                    &temp_rhs,
                                    &is_local) ||
            !IsSyntheticRegisterTempName(temp_name) ||
            !refii::lua::IsValidLuaIdentifier(temp_rhs) ||
            refii::lua::IsLuaKeyword(temp_rhs) ||
            temp_rhs == temp_name ||
            refii::lua::CountIdentifierUses(lines[line_index + 1], temp_name) != 1 ||
            IsFastSyntheticTempReferencedBeforeNextAssignment(lines,
                                                              line_index + 2,
                                                              temp_name)) {
            continue;
        }

        const std::size_t use =
            refii::lua::FindIdentifierUse(lines[line_index + 1], temp_name);
        if (use == std::string::npos) {
            continue;
        }
        lines[line_index + 1].replace(use, temp_name.size(), temp_rhs);
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(line_index));
        changed = true;
        if (line_index > 0) {
            --line_index;
        }
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool IsFastBalancedLuaExpression(std::string_view value);
bool IsFastNumericLiteral(std::string_view value);
bool IsFastSafeCallCalleeName(std::string_view callee);
std::string FastTrimRedundantOuterParentheses(std::string_view value);
bool CollectFastInlineTableLiteralEntries(std::string_view value,
                                          std::vector<std::string>* entries_out);
bool SplitFastTopLevelCommaArguments(std::string_view value,
                                     std::vector<std::string>* arguments_out);
bool ParseFastLuaCallLine(std::string_view line,
                          std::string* callee_out,
                          std::vector<std::string>* arguments_out);
