bool IsFastInlineableSyntheticExpression(std::string_view value) {
    value = internal::TrimWhitespace(value);
    if (value.empty() || internal::ContainsWord(value, "function") ||
        value.find('{') != std::string_view::npos ||
        value.find('}') != std::string_view::npos) {
        return false;
    }
    return IsFastBalancedLuaExpression(value);
}

bool FoldFastBoundedHotspotSingleUseSyntheticExpressions(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;
    for (std::size_t line_index = 0; line_index + 1 < lines.size(); ++line_index) {
        std::string temp_name;
        std::string temp_rhs;
        bool is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index],
                                    &temp_name,
                                    &temp_rhs,
                                    &is_local) ||
            !IsSyntheticRegisterTempName(temp_name) ||
            !IsFastInlineableSyntheticExpression(temp_rhs) ||
            refii::lua::CountIdentifierUses(lines[line_index + 1], temp_name) != 1 ||
            IsFastSyntheticTempReferencedBeforeNextAssignment(lines,
                                                              line_index + 2,
                                                              temp_name)) {
            continue;
        }

        const std::size_t use =
            refii::lua::FindIdentifierUse(lines[line_index + 1], temp_name);
        if (use == std::string::npos) {
            continue;
        }
        lines[line_index + 1].replace(use, temp_name.size(), temp_rhs);
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(line_index));
        changed = true;
        if (line_index > 0) {
            --line_index;
        }
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool RemoveFastBoundedHotspotDuplicateEmptyTableAssignments(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;
    for (std::size_t line_index = 1; line_index < lines.size(); ++line_index) {
        const std::string_view current =
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index]));
        const std::string_view previous =
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index - 1]));
        if (current.empty() || current != previous ||
            !internal::EndsWith(current, "= {}")) {
            continue;
        }

        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(line_index));
        --line_index;
        changed = true;
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool IsFastBoundedHotspotSafeDottedName(std::string_view value) {
    value = internal::TrimWhitespace(value);
    if (value.empty() || value.front() == '.' || value.back() == '.') {
        return false;
    }

    while (!value.empty()) {
        const std::size_t dot = value.find('.');
        const std::string_view segment =
            dot == std::string_view::npos ? value : value.substr(0, dot);
        if (!refii::lua::IsValidLuaIdentifier(segment) ||
            refii::lua::IsLuaKeyword(segment)) {
            return false;
        }
        if (dot == std::string_view::npos) {
            break;
        }
        value = value.substr(dot + 1);
    }
    return true;
}

bool IsFastBoundedHotspotSafeIndexedName(std::string_view value) {
    value = internal::TrimWhitespace(value);
    if (value.empty()) {
        return false;
    }

    const auto parse_identifier = [&](std::size_t* cursor) {
        const std::size_t start = *cursor;
        if (start >= value.size() ||
            !(std::isalpha(static_cast<unsigned char>(value[start])) ||
              value[start] == '_')) {
            return false;
        }
        ++*cursor;
        while (*cursor < value.size() &&
               (std::isalnum(static_cast<unsigned char>(value[*cursor])) ||
                value[*cursor] == '_')) {
            ++*cursor;
        }
        const std::string_view identifier = value.substr(start, *cursor - start);
        return refii::lua::IsValidLuaIdentifier(identifier) &&
               !refii::lua::IsLuaKeyword(identifier);
    };

    std::size_t cursor = 0;
    if (!parse_identifier(&cursor)) {
        return false;
    }

    bool saw_index = false;
    while (cursor < value.size()) {
        if (value[cursor] == '.') {
            ++cursor;
            if (!parse_identifier(&cursor)) {
                return false;
            }
            continue;
        }
        if (value[cursor] != '[') {
            return false;
        }

        const std::size_t close = value.find(']', cursor + 1);
        if (close == std::string_view::npos) {
            return false;
        }
        const std::string key =
            FastTrimRedundantOuterParentheses(value.substr(cursor + 1,
                                                           close - cursor - 1));
        const bool safe_key =
            IsFastNumericLiteral(key) ||
            (refii::lua::IsValidLuaIdentifier(key) &&
             !refii::lua::IsLuaKeyword(key)) ||
            ((key.size() >= 2) &&
             ((key.front() == '"' && key.back() == '"') ||
              (key.front() == '\'' && key.back() == '\'')) &&
             key.find('\n') == std::string::npos &&
             key.find('\r') == std::string::npos);
        if (!safe_key) {
            return false;
        }
        saw_index = true;
        cursor = close + 1;
    }

    return saw_index;
}

bool IsFastBoundedHotspotSimpleNewCall(std::string_view value) {
    value = internal::TrimWhitespace(value);
    constexpr std::string_view kNewSuffix = ":new()";
    if (!internal::EndsWith(value, kNewSuffix)) {
        return false;
    }
    const std::string_view receiver =
        internal::TrimWhitespace(value.substr(0, value.size() - kNewSuffix.size()));
    return IsFastBoundedHotspotSafeDottedName(receiver);
}

bool IsFastBoundedHotspotConstructorCall(std::string_view value) {
    value = internal::TrimWhitespace(value);
    const std::size_t open = value.find('(');
    if (open == std::string::npos || value.empty() || value.back() != ')' ||
        value.find_first_not_of(" \t", open + 1) == std::string_view::npos) {
        return false;
    }
    const std::string_view callee = internal::TrimWhitespace(value.substr(0, open));
    return IsFastBoundedHotspotSafeDottedName(callee) &&
           (internal::EndsWith(callee, ".New") ||
            internal::EndsWith(callee, ":new") ||
            internal::EndsWith(callee, ".Create") ||
            internal::EndsWith(callee, ":Create"));
}

std::string FastTrimRedundantOuterParentheses(std::string_view value) {
    value = internal::TrimWhitespace(value);
    while (value.size() >= 2 && value.front() == '(' && value.back() == ')') {
        int depth = 0;
        bool wraps_all = true;
        bool in_single_quote = false;
        bool in_double_quote = false;
        for (std::size_t index = 0; index < value.size(); ++index) {
            const char ch = value[index];
            if (in_single_quote) {
                if (ch == '\\' && index + 1 < value.size()) {
                    ++index;
                } else if (ch == '\'') {
                    in_single_quote = false;
                }
                continue;
            }
            if (in_double_quote) {
                if (ch == '\\' && index + 1 < value.size()) {
                    ++index;
                } else if (ch == '"') {
                    in_double_quote = false;
                }
                continue;
            }
            if (ch == '\'') {
                in_single_quote = true;
                continue;
            }
            if (ch == '"') {
                in_double_quote = true;
                continue;
            }
            if (ch == '(') {
                ++depth;
            } else if (ch == ')') {
                if (--depth < 0) {
                    wraps_all = false;
                    break;
                }
                if (depth == 0 && index + 1 < value.size()) {
                    wraps_all = false;
                    break;
                }
            }
        }
        if (!wraps_all || in_single_quote || in_double_quote || depth != 0) {
            break;
        }
        value = internal::TrimWhitespace(value.substr(1, value.size() - 2));
    }
    return std::string(value);
}

bool IsFastBoundedHotspotSafeCallExpression(std::string_view value) {
    const std::string trimmed = FastTrimRedundantOuterParentheses(value);
    std::string callee;
    std::vector<std::string> arguments;
    return ParseFastLuaCallLine(trimmed, &callee, &arguments);
}

bool IsFastBoundedHotspotSafeComparisonOperand(std::string_view value) {
    const std::string trimmed = FastTrimRedundantOuterParentheses(value);
    if (trimmed.empty()) {
        return false;
    }
    if (IsFastBoundedHotspotSafeDottedName(trimmed)) {
        return true;
    }
    if (IsFastNumericLiteral(trimmed)) {
        return true;
    }
    return false;
}

bool IsFastBoundedHotspotSafeArithmeticComparisonOperand(std::string_view value) {
    const std::string trimmed = FastTrimRedundantOuterParentheses(value);
    if (trimmed.empty() ||
        trimmed.find(',') != std::string::npos ||
        trimmed.find('{') != std::string::npos ||
        trimmed.find('=') != std::string::npos ||
        trimmed.find("function") != std::string::npos) {
        return false;
    }
    const bool has_arithmetic =
        trimmed.find('+') != std::string::npos ||
        trimmed.find('-') != std::string::npos ||
        trimmed.find('*') != std::string::npos ||
        trimmed.find('/') != std::string::npos;
    if (!has_arithmetic) {
        return false;
    }
    for (const char ch : trimmed) {
        if (std::isalnum(static_cast<unsigned char>(ch)) != 0 ||
            ch == '_' || ch == '.' || ch == ':' || ch == '(' || ch == ')' ||
            ch == ' ' || ch == '\t' || ch == '+' || ch == '-' || ch == '*' ||
            ch == '/') {
            continue;
        }
        return false;
    }
    return true;
}

bool FindFastTopLevelComparison(std::string_view value,
                                std::size_t* operator_pos,
                                std::string* operator_text) {
    if (operator_pos == nullptr || operator_text == nullptr) {
        return false;
    }

    int paren_depth = 0;
    int brace_depth = 0;
    int bracket_depth = 0;
    bool in_single_quote = false;
    bool in_double_quote = false;
    for (std::size_t index = 0; index < value.size(); ++index) {
        const char ch = value[index];
        if (in_single_quote) {
            if (ch == '\\' && index + 1 < value.size()) {
                ++index;
            } else if (ch == '\'') {
                in_single_quote = false;
            }
            continue;
        }
        if (in_double_quote) {
            if (ch == '\\' && index + 1 < value.size()) {
                ++index;
            } else if (ch == '"') {
                in_double_quote = false;
            }
            continue;
        }
        if (ch == '\'') {
            in_single_quote = true;
            continue;
        }
        if (ch == '"') {
            in_double_quote = true;
            continue;
        }
        switch (ch) {
        case '(':
            ++paren_depth;
            break;
        case ')':
            if (--paren_depth < 0) {
                return false;
            }
            break;
        case '{':
            ++brace_depth;
            break;
        case '}':
            if (--brace_depth < 0) {
                return false;
            }
            break;
        case '[':
            ++bracket_depth;
            break;
        case ']':
            if (--bracket_depth < 0) {
                return false;
            }
            break;
        case '<':
        case '>':
            if (paren_depth == 0 && brace_depth == 0 && bracket_depth == 0) {
                *operator_pos = index;
                if (index + 1 < value.size() && value[index + 1] == '=') {
                    *operator_text = std::string(value.substr(index, 2));
                } else {
                    *operator_text = std::string(value.substr(index, 1));
                }
                return true;
            }
            break;
        default:
            break;
        }
    }
    return false;
}

std::string FastFlippedComparisonOperator(std::string_view comparison_operator) {
    if (comparison_operator == "<") {
        return ">";
    }
    if (comparison_operator == "<=") {
        return ">=";
    }
    if (comparison_operator == ">") {
        return "<";
    }
    if (comparison_operator == ">=") {
        return "<=";
    }
    return std::string();
}

bool IsFastLooseSafeCallExpression(std::string_view value);

bool TryFlipFastSafeRelationalSegment(std::string_view segment,
                                      std::string* flipped_out) {
    if (flipped_out == nullptr) {
        return false;
    }

    const std::string segment_storage = FastTrimRedundantOuterParentheses(segment);
    std::size_t operator_pos = std::string::npos;
    std::string comparison_operator;
    if (!FindFastTopLevelComparison(segment_storage,
                                    &operator_pos,
                                    &comparison_operator)) {
        return false;
    }

    const std::string flipped_operator =
        FastFlippedComparisonOperator(comparison_operator);
    if (flipped_operator.empty()) {
        return false;
    }

    const std::size_t operator_width = comparison_operator.size();
    const std::string left = FastTrimRedundantOuterParentheses(
        std::string_view(segment_storage).substr(0, operator_pos));
    const std::string right = FastTrimRedundantOuterParentheses(
        std::string_view(segment_storage).substr(operator_pos + operator_width));
    const bool safe_plain_compare =
        IsFastBoundedHotspotSafeComparisonOperand(left) &&
        IsFastBoundedHotspotSafeComparisonOperand(right);
    const bool safe_numeric_call_compare =
        (IsFastNumericLiteral(left) &&
         (IsFastBoundedHotspotSafeCallExpression(right) ||
          IsFastLooseSafeCallExpression(right))) ||
        (IsFastNumericLiteral(right) &&
         (IsFastBoundedHotspotSafeCallExpression(left) ||
          IsFastLooseSafeCallExpression(left)));
    const bool safe_member_call_compare =
        (IsFastBoundedHotspotSafeComparisonOperand(left) &&
         !IsFastNumericLiteral(left) &&
         (IsFastBoundedHotspotSafeCallExpression(right) ||
          IsFastLooseSafeCallExpression(right))) ||
        (IsFastBoundedHotspotSafeComparisonOperand(right) &&
         !IsFastNumericLiteral(right) &&
         (IsFastBoundedHotspotSafeCallExpression(left) ||
          IsFastLooseSafeCallExpression(left)));
    const bool safe_call_call_compare =
        (IsFastBoundedHotspotSafeCallExpression(left) ||
         IsFastLooseSafeCallExpression(left)) &&
        (IsFastBoundedHotspotSafeCallExpression(right) ||
         IsFastLooseSafeCallExpression(right));
    if (!safe_plain_compare && !safe_numeric_call_compare &&
        !safe_member_call_compare && !safe_call_call_compare) {
        return false;
    }

    *flipped_out = right + " " + flipped_operator + " " + left;
    return true;
}

bool TryFlipFastFirstCompoundRelationalSegment(std::string_view condition,
                                               std::string* flipped_out) {
    if (flipped_out == nullptr) {
        return false;
    }

    const std::string condition_storage = FastTrimRedundantOuterParentheses(condition);
    struct Segment {
        std::size_t start = 0;
        std::size_t end = 0;
    };
    std::vector<Segment> segments;
    std::size_t segment_start = 0;
    int paren_depth = 0;
    int brace_depth = 0;
    int bracket_depth = 0;
    bool in_single_quote = false;
    bool in_double_quote = false;
    bool saw_connector = false;

    for (std::size_t index = 0; index < condition_storage.size(); ++index) {
        const char ch = condition_storage[index];
        if (in_single_quote) {
            if (ch == '\\' && index + 1 < condition_storage.size()) {
                ++index;
            } else if (ch == '\'') {
                in_single_quote = false;
            }
            continue;
        }
        if (in_double_quote) {
            if (ch == '\\' && index + 1 < condition_storage.size()) {
                ++index;
            } else if (ch == '"') {
                in_double_quote = false;
            }
            continue;
        }
        if (ch == '\'') {
            in_single_quote = true;
            continue;
        }
        if (ch == '"') {
            in_double_quote = true;
            continue;
        }
        switch (ch) {
        case '(':
            ++paren_depth;
            break;
        case ')':
            --paren_depth;
            break;
        case '{':
            ++brace_depth;
            break;
        case '}':
            --brace_depth;
            break;
        case '[':
            ++bracket_depth;
            break;
        case ']':
            --bracket_depth;
            break;
        default:
            break;
        }
        if (paren_depth != 0 || brace_depth != 0 || bracket_depth != 0) {
            continue;
        }
        if (condition_storage.compare(index, 4, " or ") == 0 ||
            condition_storage.compare(index, 5, " and ") == 0) {
            segments.push_back({segment_start, index});
            segment_start =
                index + (condition_storage.compare(index, 4, " or ") == 0 ? 4 : 5);
            saw_connector = true;
        }
    }
    if (!saw_connector) {
        return false;
    }
    segments.push_back({segment_start, condition_storage.size()});

    for (const Segment& segment : segments) {
        const std::string_view raw_segment(condition_storage.data() + segment.start,
                                           segment.end - segment.start);
        const std::string_view trimmed_segment = internal::TrimWhitespace(raw_segment);
        if (trimmed_segment.empty() ||
            internal::StartsWith(trimmed_segment, "not ")) {
            continue;
        }
        std::string flipped_segment;
        if (!TryFlipFastSafeRelationalSegment(trimmed_segment, &flipped_segment)) {
            continue;
        }

        std::string rewritten = condition_storage;
        const std::size_t trim_left =
            static_cast<std::size_t>(trimmed_segment.data() - raw_segment.data());
        const std::size_t replace_start = segment.start + trim_left;
        rewritten.replace(replace_start, trimmed_segment.size(), flipped_segment);
        *flipped_out = std::move(rewritten);
        return true;
    }
    return false;
}

bool IsFastLooseSafeCallExpression(std::string_view value) {
    const std::string trimmed = FastTrimRedundantOuterParentheses(value);
    if (trimmed.empty() || trimmed.back() != ')') {
        return false;
    }
    const std::size_t open = trimmed.find('(');
    if (open == std::string::npos || open == 0) {
        return false;
    }
    const std::string_view callee =
        internal::TrimWhitespace(std::string_view(trimmed).substr(0, open));
    const std::string_view args = std::string_view(trimmed).substr(
        open + 1,
        trimmed.size() - open - 2);
    return IsFastSafeCallCalleeName(callee) && IsFastBalancedLuaExpression(args);
}

bool TryFlipFastNumericLeftCallComparison(std::string_view condition,
                                          std::string* flipped_out) {
    if (flipped_out == nullptr) {
        return false;
    }
    const std::string condition_storage = FastTrimRedundantOuterParentheses(condition);
    std::size_t operator_pos = std::string::npos;
    std::string comparison_operator;
    if (!FindFastTopLevelComparison(condition_storage,
                                    &operator_pos,
                                    &comparison_operator)) {
        return false;
    }
    const std::string flipped_operator =
        FastFlippedComparisonOperator(comparison_operator);
    if (flipped_operator.empty()) {
        return false;
    }

    const std::size_t operator_width = comparison_operator.size();
    const std::string left = FastTrimRedundantOuterParentheses(
        std::string_view(condition_storage).substr(0, operator_pos));
    const std::string right = FastTrimRedundantOuterParentheses(
        std::string_view(condition_storage).substr(operator_pos + operator_width));
    if (!IsFastNumericLiteral(left) ||
        (!IsFastBoundedHotspotSafeCallExpression(right) &&
         !IsFastLooseSafeCallExpression(right))) {
        return false;
    }

    *flipped_out = right + " " + flipped_operator + " " + left;
    return true;
}

bool TryFlipFastLooseNumericLeftCallComparison(std::string_view condition,
                                               std::string* flipped_out) {
    if (flipped_out == nullptr) {
        return false;
    }
    const std::string condition_storage = FastTrimRedundantOuterParentheses(condition);
    constexpr std::array<std::pair<std::string_view, std::string_view>, 4> kOps = {{
        {" <= ", ">="},
        {" >= ", "<="},
        {" < ", ">"},
        {" > ", "<"},
    }};
    for (const auto& [op, flipped_op] : kOps) {
        const std::size_t op_pos = condition_storage.find(op);
        if (op_pos == std::string::npos) {
            continue;
        }
        const std::string left = FastTrimRedundantOuterParentheses(
            std::string_view(condition_storage).substr(0, op_pos));
        const std::string right = FastTrimRedundantOuterParentheses(
            std::string_view(condition_storage).substr(op_pos + op.size()));
        if (!IsFastNumericLiteral(left) || right.empty() ||
            right.find('(') == std::string::npos || right.back() != ')' ||
            (!IsFastBoundedHotspotSafeCallExpression(right) &&
             !IsFastLooseSafeCallExpression(right))) {
            continue;
        }
        *flipped_out = right + " " + std::string(flipped_op) + " " + left;
        return true;
    }
    return false;
}

bool FlipFastBoundedHotspotRelationalIfOrientation(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;
    for (std::string& line : lines) {
        const std::string_view stripped = internal::StripLineComment(line);
        if (stripped.size() != line.size()) {
            continue;
        }
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        if (!internal::StartsWith(trimmed, "if ") ||
            !internal::EndsWith(trimmed, " then")) {
            continue;
        }

        const std::string condition_storage = FastTrimRedundantOuterParentheses(
            trimmed.substr(3, trimmed.size() - 3 - 5));
        std::string_view condition = condition_storage;
        std::size_t operator_pos = std::string::npos;
        std::string comparison_operator;
        if (!FindFastTopLevelComparison(condition,
                                        &operator_pos,
                                        &comparison_operator)) {
            continue;
        }
        const std::string flipped_operator =
            FastFlippedComparisonOperator(comparison_operator);
        if (flipped_operator.empty()) {
            continue;
        }

        const std::size_t operator_width = comparison_operator.size();
        const std::string left = FastTrimRedundantOuterParentheses(
            condition.substr(0, operator_pos));
        const std::string right = FastTrimRedundantOuterParentheses(
            condition.substr(operator_pos + operator_width));
        const bool safe_plain_compare =
            IsFastBoundedHotspotSafeComparisonOperand(left) &&
            IsFastBoundedHotspotSafeComparisonOperand(right);
        const bool safe_numeric_call_compare =
            (IsFastNumericLiteral(left) &&
             (IsFastBoundedHotspotSafeCallExpression(right) ||
              IsFastLooseSafeCallExpression(right))) ||
            (IsFastNumericLiteral(right) &&
             (IsFastBoundedHotspotSafeCallExpression(left) ||
              IsFastLooseSafeCallExpression(left)));
        const bool safe_member_call_compare =
            (IsFastBoundedHotspotSafeComparisonOperand(left) &&
             !IsFastNumericLiteral(left) &&
             (IsFastBoundedHotspotSafeCallExpression(right) ||
              IsFastLooseSafeCallExpression(right))) ||
            (IsFastBoundedHotspotSafeComparisonOperand(right) &&
             !IsFastNumericLiteral(right) &&
             (IsFastBoundedHotspotSafeCallExpression(left) ||
              IsFastLooseSafeCallExpression(left)));
        const bool safe_arithmetic_call_compare =
            (IsFastBoundedHotspotSafeArithmeticComparisonOperand(left) &&
             (IsFastBoundedHotspotSafeCallExpression(right) ||
              IsFastLooseSafeCallExpression(right))) ||
            (IsFastBoundedHotspotSafeArithmeticComparisonOperand(right) &&
             (IsFastBoundedHotspotSafeCallExpression(left) ||
              IsFastLooseSafeCallExpression(left)));
        if (!safe_plain_compare && !safe_numeric_call_compare &&
            !safe_member_call_compare && !safe_arithmetic_call_compare) {
            continue;
        }

        line = internal::GetLuaLineIndent(line) + "if " + right + " " +
               flipped_operator + " " + left + " then";
        changed = true;
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool FlipFastBoundedHotspotCompoundRelationalIfOrientation(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::string& line : lines) {
        const std::string_view stripped = internal::StripLineComment(line);
        if (stripped.size() != line.size()) {
            continue;
        }
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        if (!internal::StartsWith(trimmed, "if ") ||
            !internal::EndsWith(trimmed, " then") ||
            (trimmed.find(" or ") == std::string_view::npos &&
             trimmed.find(" and ") == std::string_view::npos)) {
            continue;
        }

        const std::string condition_storage = FastTrimRedundantOuterParentheses(
            trimmed.substr(3, trimmed.size() - 3 - 5));
        std::string flipped_condition;
        if (!TryFlipFastFirstCompoundRelationalSegment(condition_storage,
                                                       &flipped_condition)) {
            continue;
        }

        line = internal::GetLuaLineIndent(line) + "if " + flipped_condition +
               " then";
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }
    return false;
}

bool FoldFastBoundedHotspotOpenRangeOrReturnToAnd(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;

    for (std::string& line : lines) {
        const std::string_view stripped = internal::StripLineComment(line);
        if (stripped.size() != line.size()) {
            continue;
        }
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        if (!internal::StartsWith(trimmed, "return ") ||
            trimmed.find(" or ") == std::string_view::npos) {
            continue;
        }

        const std::string expression =
            FastTrimRedundantOuterParentheses(trimmed.substr(7));
        const std::size_t left_operator_pos = expression.find(" < ");
        const std::size_t or_pos = expression.find(" or ", left_operator_pos);
        const std::size_t right_operator_pos = expression.find(" <= ", or_pos);
        if (left_operator_pos == std::string::npos ||
            or_pos == std::string::npos ||
            right_operator_pos == std::string::npos ||
            !(left_operator_pos < or_pos && or_pos < right_operator_pos)) {
            continue;
        }

        const std::string left_segment = FastTrimRedundantOuterParentheses(
            std::string_view(expression).substr(0, or_pos));
        const std::string right_segment = FastTrimRedundantOuterParentheses(
            std::string_view(expression).substr(or_pos + 4));
        std::size_t left_segment_operator_pos = std::string::npos;
        std::size_t right_segment_operator_pos = std::string::npos;
        std::string left_operator;
        std::string right_operator;
        if (!FindFastTopLevelComparison(left_segment,
                                        &left_segment_operator_pos,
                                        &left_operator) ||
            !FindFastTopLevelComparison(right_segment,
                                        &right_segment_operator_pos,
                                        &right_operator) ||
            left_operator != "<" ||
            right_operator != "<=") {
            continue;
        }

        const std::string left_expr = FastTrimRedundantOuterParentheses(
            std::string_view(left_segment).substr(0, left_segment_operator_pos));
        const std::string bound = FastTrimRedundantOuterParentheses(
            std::string_view(left_segment).substr(left_segment_operator_pos + 1));
        const std::string mirrored_bound = FastTrimRedundantOuterParentheses(
            std::string_view(right_segment).substr(0, right_segment_operator_pos));
        const std::string right_expr = FastTrimRedundantOuterParentheses(
            std::string_view(right_segment).substr(right_segment_operator_pos + 2));
        const auto is_safe_range_expr = [](std::string_view value) {
            const std::string trimmed = FastTrimRedundantOuterParentheses(value);
            return !trimmed.empty() &&
                   trimmed.find(',') == std::string::npos &&
                   trimmed.find('{') == std::string::npos &&
                   trimmed.find('=') == std::string::npos &&
                   trimmed.find("function") == std::string::npos &&
                   IsFastBalancedLuaExpression(trimmed);
        };
        if (left_expr.empty() || right_expr.empty() || bound.empty() ||
            bound != mirrored_bound ||
            !is_safe_range_expr(bound) ||
            !is_safe_range_expr(left_expr) ||
            !is_safe_range_expr(right_expr)) {
            continue;
        }

        line = internal::GetLuaLineIndent(line) + "return " + left_expr +
               " < " + bound + " and " + right_expr + " < " + bound;
        changed = true;
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

std::optional<std::size_t> FindFastTopLevelAndOperator(std::string_view condition) {
    int paren_depth = 0;
    int brace_depth = 0;
    int bracket_depth = 0;
    bool in_single_quote = false;
    bool in_double_quote = false;
    for (std::size_t index = 0; index < condition.size(); ++index) {
        const char ch = condition[index];
        if (in_single_quote) {
            if (ch == '\\' && index + 1 < condition.size()) {
                ++index;
            } else if (ch == '\'') {
                in_single_quote = false;
            }
            continue;
        }
        if (in_double_quote) {
            if (ch == '\\' && index + 1 < condition.size()) {
                ++index;
            } else if (ch == '"') {
                in_double_quote = false;
            }
            continue;
        }
        if (ch == '\'') {
            in_single_quote = true;
            continue;
        }
        if (ch == '"') {
            in_double_quote = true;
            continue;
        }
        switch (ch) {
        case '(':
            ++paren_depth;
            break;
        case ')':
            --paren_depth;
            break;
        case '{':
            ++brace_depth;
            break;
        case '}':
            --brace_depth;
            break;
        case '[':
            ++bracket_depth;
            break;
        case ']':
            --bracket_depth;
            break;
        default:
            break;
        }
        if (paren_depth != 0 || brace_depth != 0 || bracket_depth != 0) {
            continue;
        }
        if (condition.compare(index, 5, " and ") == 0) {
            return index;
        }
    }
    return std::nullopt;
}

