bool FindFastLuaTopLevelElse(const std::vector<std::string>& lines,
                             std::size_t if_line,
                             std::size_t if_end,
                             std::size_t* else_line_out) {
    if (else_line_out == nullptr || if_line >= lines.size() || if_end >= lines.size() ||
        if_line >= if_end) {
        return false;
    }

    int nested_depth = 0;
    for (std::size_t line_index = if_line + 1; line_index < if_end; ++line_index) {
        const std::string_view trimmed =
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index]));
        if (FastLuaLineStartsBlock(trimmed)) {
            ++nested_depth;
            continue;
        }
        if (trimmed == "end" || internal::StartsWith(trimmed, "until ")) {
            if (nested_depth > 0) {
                --nested_depth;
            }
            continue;
        }
        if (nested_depth == 0 && trimmed == "else") {
            *else_line_out = line_index;
            return true;
        }
    }
    return false;
}

bool ExpandFastBoundedHotspotAndElseGuardToNestedIf(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        const std::string_view stripped = internal::StripLineComment(lines[line_index]);
        if (stripped.size() != lines[line_index].size()) {
            continue;
        }
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        if (!internal::StartsWith(trimmed, "if ") ||
            !internal::EndsWith(trimmed, " then") ||
            trimmed.find(" and ") == std::string_view::npos ||
            trimmed.find(" or ") != std::string_view::npos) {
            continue;
        }

        const std::string condition = FastTrimRedundantOuterParentheses(
            trimmed.substr(3, trimmed.size() - 3 - 5));
        const std::optional<std::size_t> and_pos =
            FindFastTopLevelAndOperator(condition);
        if (!and_pos.has_value()) {
            continue;
        }

        const std::string left = FastTrimRedundantOuterParentheses(
            std::string_view(condition).substr(0, and_pos.value()));
        const std::string right = FastTrimRedundantOuterParentheses(
            std::string_view(condition).substr(and_pos.value() + 5));
        if (left.empty() || right.empty() ||
            !IsFastBalancedLuaExpression(left) ||
            !IsFastBalancedLuaExpression(right) ||
            internal::ContainsWord(left, "function") ||
            internal::ContainsWord(right, "function")) {
            continue;
        }

        std::size_t if_end = 0;
        std::size_t else_line = 0;
        if (!FindFastLuaMatchingEnd(lines, line_index, &if_end) ||
            !FindFastLuaTopLevelElse(lines, line_index, if_end, &else_line) ||
            else_line <= line_index + 1) {
            continue;
        }

        const std::string indent = internal::GetLuaLineIndent(lines[line_index]);
        lines[line_index] = indent + "if " + left + " then";
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(line_index + 1),
                     indent + "if " + right + " then");
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(else_line + 1),
                     indent + "end");
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }
    return false;
}

bool FlipFastBoundedHotspotFirstIndexedNumericLeftIfOrientation(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::string& line : lines) {
        const std::string_view stripped = internal::StripLineComment(line);
        if (stripped.size() != line.size()) {
            continue;
        }
        const std::string_view trimmed = internal::TrimWhitespace(stripped);
        if (!internal::StartsWith(trimmed, "if ") ||
            !internal::EndsWith(trimmed, " then")) {
            continue;
        }

        const std::string condition_storage = FastTrimRedundantOuterParentheses(
            trimmed.substr(3, trimmed.size() - 3 - 5));
        std::size_t operator_pos = std::string::npos;
        std::string comparison_operator;
        if (!FindFastTopLevelComparison(condition_storage,
                                        &operator_pos,
                                        &comparison_operator)) {
            continue;
        }
        if (comparison_operator != "<" && comparison_operator != "<=") {
            continue;
        }

        const std::string left = FastTrimRedundantOuterParentheses(
            std::string_view(condition_storage).substr(0, operator_pos));
        const std::string right = FastTrimRedundantOuterParentheses(
            std::string_view(condition_storage)
                .substr(operator_pos + comparison_operator.size()));
        if (!IsFastNumericLiteral(left) ||
            !IsFastBoundedHotspotSafeIndexedName(right)) {
            continue;
        }

        line = internal::GetLuaLineIndent(line) + "if " + right + " " +
               FastFlippedComparisonOperator(comparison_operator) + " " + left +
               " then";
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }
    return false;
}

bool FoldFastBoundedHotspotAdjacentNumericCallGuardToAnd(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t line_index = 0; line_index + 3 < lines.size(); ++line_index) {
        if (internal::StripLineComment(lines[line_index]).size() !=
                lines[line_index].size() ||
            internal::StripLineComment(lines[line_index + 1]).size() !=
                lines[line_index + 1].size()) {
            continue;
        }

        const std::string outer_condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index])));
        const std::string inner_condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index + 1])));
        std::string flipped_inner_condition;
        if (outer_condition.empty() || inner_condition.empty() ||
            (!TryFlipFastNumericLeftCallComparison(inner_condition,
                                                   &flipped_inner_condition) &&
             !TryFlipFastLooseNumericLeftCallComparison(inner_condition,
                                                        &flipped_inner_condition))) {
            continue;
        }

        std::size_t inner_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, line_index + 1, &inner_end) ||
            inner_end + 1 >= lines.size() ||
            internal::TrimWhitespace(internal::StripLineComment(lines[inner_end + 1])) !=
                "end") {
            continue;
        }

        bool has_else = false;
        for (std::size_t body_line = line_index + 2; body_line < inner_end; ++body_line) {
            const std::string_view trimmed =
                internal::TrimWhitespace(internal::StripLineComment(lines[body_line]));
            if (trimmed == "else" || internal::StartsWith(trimmed, "elseif ")) {
                has_else = true;
                break;
            }
        }
        if (has_else) {
            continue;
        }

        lines[line_index] = internal::GetLuaLineIndent(lines[line_index]) +
                            "if " + outer_condition + " and " +
                            flipped_inner_condition + " then";
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(inner_end + 1));
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(line_index + 1));
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool FastLuaIfBlockHasSameLevelElse(const std::vector<std::string>& lines,
                                    std::size_t if_line,
                                    std::size_t end_line) {
    int nested_depth = 0;
    for (std::size_t line_index = if_line + 1; line_index < end_line; ++line_index) {
        const std::string_view trimmed =
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index]));
        if (FastLuaLineStartsBlock(trimmed)) {
            ++nested_depth;
            continue;
        }
        if (trimmed == "end" || internal::StartsWith(trimmed, "until ")) {
            if (nested_depth > 0) {
                --nested_depth;
            }
            continue;
        }
        if (nested_depth == 0 &&
            (trimmed == "else" || internal::StartsWith(trimmed, "elseif "))) {
            return true;
        }
    }
    return false;
}

bool FastLuaBlockAssignsCurrentState(const std::vector<std::string>& lines,
                                     std::size_t first_line,
                                     std::size_t end_line) {
    for (std::size_t line_index = first_line; line_index < end_line; ++line_index) {
        std::string lhs;
        std::string rhs;
        bool is_local = false;
        if (ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) &&
            !is_local && lhs.find(".CurrentState") != std::string::npos) {
            return true;
        }
    }
    return false;
}

bool FastLuaRangeContainsSafeCall(const std::vector<std::string>& lines,
                                  std::size_t first_line,
                                  std::size_t end_line) {
    for (std::size_t line_index = first_line; line_index < end_line; ++line_index) {
        std::string callee;
        std::vector<std::string> arguments;
        if (ParseFastLuaCallLine(lines[line_index], &callee, &arguments)) {
            return true;
        }
    }
    return false;
}

bool FastLuaFindElseTailEnd(const std::vector<std::string>& lines,
                            std::size_t tail_start,
                            std::size_t* tail_end_exclusive) {
    if (tail_end_exclusive == nullptr || tail_start >= lines.size()) {
        return false;
    }

    std::size_t cursor = tail_start;
    std::size_t consumed_content_lines = 0;
    bool saw_call = false;
    bool saw_non_yield_call = false;
    while (cursor < lines.size()) {
        const std::string_view trimmed =
            internal::TrimWhitespace(internal::StripLineComment(lines[cursor]));
        if (trimmed.empty()) {
            return false;
        }
        if (trimmed == "end" || trimmed == "else" ||
            internal::StartsWith(trimmed, "elseif ")) {
            break;
        }

        std::string callee;
        std::vector<std::string> arguments;
        if (ParseFastLuaCallLine(lines[cursor], &callee, &arguments)) {
            saw_call = true;
            if (callee != "coroutine.yield") {
                saw_non_yield_call = true;
            }
            ++cursor;
            ++consumed_content_lines;
            continue;
        }

        if (internal::StartsWith(trimmed, "if ") &&
            internal::EndsWith(trimmed, " then")) {
            std::size_t nested_end = std::string::npos;
            if (!FindFastLuaMatchingEnd(lines, cursor, &nested_end) ||
                FastLuaIfBlockHasSameLevelElse(lines, cursor, nested_end) ||
                nested_end >= lines.size()) {
                return false;
            }
            saw_call = saw_call || FastLuaRangeContainsSafeCall(lines,
                                                                cursor + 1,
                                                                nested_end);
            consumed_content_lines += nested_end - cursor + 1;
            cursor = nested_end + 1;
            continue;
        }

        return false;
    }

    if (!saw_call || !saw_non_yield_call || consumed_content_lines == 0 ||
        consumed_content_lines > 12 ||
        cursor >= lines.size()) {
        return false;
    }
    const std::string_view stop =
        internal::TrimWhitespace(internal::StripLineComment(lines[cursor]));
    if (stop != "end" && stop != "else" && !internal::StartsWith(stop, "elseif ")) {
        return false;
    }

    *tail_end_exclusive = cursor;
    return true;
}

bool FoldFastBoundedHotspotPostStateTailToElse(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        const std::string condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index])));
        if (condition.empty() || !IsFastBalancedLuaExpression(condition)) {
            continue;
        }

        std::size_t if_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, line_index, &if_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, line_index, if_end) ||
            !FastLuaBlockAssignsCurrentState(lines, line_index + 1, if_end)) {
            continue;
        }

        const std::size_t tail_start = FastNextContentLine(lines, if_end + 1);
        std::size_t tail_end_exclusive = std::string::npos;
        if (!FastLuaFindElseTailEnd(lines, tail_start, &tail_end_exclusive)) {
            continue;
        }

        lines[if_end] = internal::GetLuaLineIndent(lines[if_end]) + "else";
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(tail_end_exclusive),
                     internal::GetLuaLineIndent(lines[if_end]) + "end");
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool FoldFastBoundedHotspotPostIfCallTailToElse(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    constexpr std::size_t kMaxGuardBodyLines = 32;
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        const std::string condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index])));
        if (condition.empty() ||
            !internal::StartsWith(internal::TrimWhitespace(condition), "not ") ||
            !IsFastBalancedLuaExpression(condition)) {
            continue;
        }

        std::size_t if_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, line_index, &if_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, line_index, if_end) ||
            if_end <= line_index ||
            if_end - line_index > kMaxGuardBodyLines ||
            !FastLuaRangeContainsSafeCall(lines, line_index + 1, if_end)) {
            continue;
        }

        const std::size_t tail_line = FastNextContentLine(lines, if_end + 1);
        if (tail_line >= lines.size() || tail_line != if_end + 1) {
            continue;
        }

        std::string callee;
        std::vector<std::string> arguments;
        if (!ParseFastLuaCallLine(lines[tail_line], &callee, &arguments) ||
            callee != "print" ||
            tail_line + 1 >= lines.size()) {
            continue;
        }

        const std::string_view next_trimmed = internal::TrimWhitespace(
            internal::StripLineComment(lines[tail_line + 1]));
        if (next_trimmed.empty() || next_trimmed == "end" ||
            next_trimmed == "else" ||
            internal::StartsWith(next_trimmed, "elseif ")) {
            continue;
        }

        lines[if_end] = internal::GetLuaLineIndent(lines[if_end]) + "else";
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(tail_line + 1),
                     internal::GetLuaLineIndent(lines[if_end]) + "end");
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool FoldFastBoundedHotspotPostIfAssertTailToElse(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    constexpr std::size_t kMaxGuardBodyLines = 16;
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        const std::string condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index])));
        if (condition.empty() || !IsFastBalancedLuaExpression(condition)) {
            continue;
        }

        std::size_t if_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, line_index, &if_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, line_index, if_end) ||
            if_end <= line_index ||
            if_end - line_index > kMaxGuardBodyLines ||
            !FastLuaRangeContainsSafeCall(lines, line_index + 1, if_end)) {
            continue;
        }

        const std::size_t tail_line = FastNextContentLine(lines, if_end + 1);
        if (tail_line >= lines.size() || tail_line != if_end + 1) {
            continue;
        }
        const std::string_view tail_trimmed =
            internal::TrimWhitespace(lines[tail_line]);
        if (!internal::StartsWith(tail_trimmed, "assert(") ||
            !internal::EndsWith(tail_trimmed, ")")) {
            continue;
        }

        lines[if_end] = internal::GetLuaLineIndent(lines[if_end]) + "else";
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(tail_line + 1),
                     internal::GetLuaLineIndent(lines[if_end]) + "end");
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool ParseFastIsLevelLoadedCall(std::string_view condition, std::string* argument) {
    if (argument == nullptr) {
        return false;
    }
    condition = internal::TrimWhitespace(condition);
    constexpr std::string_view kPrefix = "IsLevelLoaded(";
    if (!internal::StartsWith(condition, kPrefix) ||
        !internal::EndsWith(condition, ")")) {
        return false;
    }
    const std::string_view arg = internal::TrimWhitespace(condition.substr(
        kPrefix.size(), condition.size() - kPrefix.size() - 1));
    if (arg.empty() || !IsFastBalancedLuaExpression(arg)) {
        return false;
    }
    *argument = std::string(arg);
    return true;
}

bool FoldFastBoundedHotspotLoadedPositiveTailToElse(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    constexpr std::size_t kMaxThenBodyLines = 32;
    constexpr std::size_t kMaxElseBodyLines = 8;
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        const std::string condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index])));
        std::string level_argument;
        if (!ParseFastIsLevelLoadedCall(condition, &level_argument)) {
            continue;
        }

        std::size_t if_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, line_index, &if_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, line_index, if_end) ||
            if_end <= line_index ||
            if_end - line_index > kMaxThenBodyLines) {
            continue;
        }

        const std::size_t load_line = FastNextContentLine(lines, if_end + 1);
        if (load_line >= lines.size() || load_line != if_end + 1) {
            continue;
        }
        std::string callee;
        std::vector<std::string> arguments;
        if (!ParseFastLuaCallLine(lines[load_line], &callee, &arguments) ||
            callee != "Debug.LoadLevel") {
            continue;
        }

        const std::size_t while_line = FastNextContentLine(lines, load_line + 1);
        if (while_line >= lines.size() || while_line != load_line + 1) {
            continue;
        }
        const std::string_view while_trimmed =
            internal::TrimWhitespace(internal::StripLineComment(lines[while_line]));
        constexpr std::string_view kWhilePrefix = "while not IsLevelLoaded(";
        constexpr std::string_view kDoSuffix = ") do";
        if (!internal::StartsWith(while_trimmed, kWhilePrefix) ||
            !internal::EndsWith(while_trimmed, kDoSuffix)) {
            continue;
        }
        const std::string_view while_arg = internal::TrimWhitespace(
            while_trimmed.substr(kWhilePrefix.size(),
                                 while_trimmed.size() - kWhilePrefix.size() -
                                     kDoSuffix.size()));
        if (while_arg != level_argument) {
            continue;
        }

        std::size_t while_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, while_line, &while_end) ||
            while_end - load_line > kMaxElseBodyLines ||
            !FastLuaRangeContainsSafeCall(lines, load_line, while_end)) {
            continue;
        }

        lines[if_end] = internal::GetLuaLineIndent(lines[if_end]) + "else";
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(while_end + 1),
                     internal::GetLuaLineIndent(lines[if_end]) + "end");
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool IsFastSceneVectorTempName(std::string_view name) {
    return name == "hero" ||
           name == "facing" ||
           internal::EndsWith(name, "_pos") ||
           internal::EndsWith(name, "_dir") ||
           internal::EndsWith(name, "_face") ||
           internal::EndsWith(name, "_cam_pos");
}

bool HasFastPriorAssignmentInFunction(const std::vector<std::string>& lines,
                                      std::size_t line_index,
                                      std::string_view name) {
    while (line_index > 0) {
        --line_index;
        const std::string_view trimmed =
            internal::TrimWhitespace(internal::StripLineComment(lines[line_index]));
        if (internal::StartsWith(trimmed, "function ") ||
            internal::StartsWith(trimmed, "local function ")) {
            return false;
        }
        std::string lhs;
        std::string rhs;
        bool is_local = false;
        if (ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) &&
            lhs == name) {
            return true;
        }
    }
    return false;
}

bool FoldFastBoundedHotspotSceneVectorTempsToLocals(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;

    for (std::size_t line_index = 0; line_index + 1 < lines.size(); ++line_index) {
        std::string lhs;
        std::string rhs;
        bool is_local = false;
        std::string next_lhs;
        std::string next_rhs;
        bool next_is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) ||
            !ParseFastLuaAssignment(lines[line_index + 1],
                                    &next_lhs,
                                    &next_rhs,
                                    &next_is_local) ||
            is_local ||
            next_is_local ||
            lhs != next_lhs ||
            !IsFastSceneVectorTempName(lhs) ||
            !IsFastBoundedHotspotSafeDottedName(rhs) ||
            !internal::StartsWith(next_rhs, lhs + ".") ||
            !IsFastBoundedHotspotSafeDottedName(next_rhs) ||
            HasFastPriorAssignmentInFunction(lines, line_index, lhs)) {
            continue;
        }

        std::string replacement = internal::GetLuaLineIndent(lines[line_index]) +
                                  "local " + lhs + " = " + rhs;
        replacement += std::string_view(next_rhs).substr(lhs.size());
        lines[line_index] = std::move(replacement);
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(line_index + 1));
        changed = true;
    }

    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        std::string lhs;
        std::string rhs;
        bool is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) ||
            is_local ||
            !IsFastSceneVectorTempName(lhs) ||
            !refii::lua::IsValidLuaIdentifier(lhs) ||
            refii::lua::IsLuaKeyword(lhs) ||
            HasFastPriorAssignmentInFunction(lines, line_index, lhs) ||
            internal::ContainsWord(rhs, "function") ||
            rhs.find('{') != std::string::npos ||
            rhs.find('}') != std::string::npos ||
            !IsFastBalancedLuaExpression(rhs)) {
            continue;
        }

        const std::size_t first_non_space =
            lines[line_index].find_first_not_of(" \t");
        if (first_non_space == std::string::npos) {
            continue;
        }
        lines[line_index].insert(first_non_space, "local ");
        changed = true;
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool FoldFastBoundedHotspotNestedFlagGuardPostCallToAndElse(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t outer_line = 0; outer_line + 4 < lines.size(); ++outer_line) {
        const std::string outer_condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[outer_line])));
        if (outer_condition.empty() || !IsFastBalancedLuaExpression(outer_condition)) {
            continue;
        }

        const std::size_t inner_line = FastNextContentLine(lines, outer_line + 1);
        if (inner_line != outer_line + 1) {
            continue;
        }
        const std::string inner_condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[inner_line])));
        if (inner_condition.empty() || !IsFastBalancedLuaExpression(inner_condition)) {
            continue;
        }

        std::size_t inner_end = std::string::npos;
        std::size_t outer_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, inner_line, &inner_end) ||
            !FindFastLuaMatchingEnd(lines, outer_line, &outer_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, inner_line, inner_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, outer_line, outer_end) ||
            FastNextContentLine(lines, inner_end + 1) != outer_end) {
            continue;
        }

        std::string assigned_lhs;
        bool saw_assignment = false;
        for (std::size_t body_line = inner_line + 1; body_line < inner_end; ++body_line) {
            std::string lhs;
            std::string rhs;
            bool is_local = false;
            if (ParseFastLuaAssignment(lines[body_line], &lhs, &rhs, &is_local) &&
                !is_local && lhs.find('.') == std::string::npos &&
                refii::lua::IsValidLuaIdentifier(lhs) && !refii::lua::IsLuaKeyword(lhs)) {
                assigned_lhs = lhs;
                saw_assignment = true;
                break;
            }
        }
        if (!saw_assignment || inner_condition.find(assigned_lhs) == std::string::npos ||
            !FastLuaRangeContainsSafeCall(lines, inner_line + 1, inner_end)) {
            continue;
        }

        const std::size_t tail_line = FastNextContentLine(lines, outer_end + 1);
        std::string callee;
        std::vector<std::string> arguments;
        if (tail_line >= lines.size() ||
            !ParseFastLuaCallLine(lines[tail_line], &callee, &arguments)) {
            continue;
        }
        const std::size_t tail_stop = FastNextContentLine(lines, tail_line + 1);
        if (tail_stop >= lines.size()) {
            continue;
        }
        const std::string_view stop =
            internal::TrimWhitespace(internal::StripLineComment(lines[tail_stop]));
        if (stop != "end" && stop != "else" && !internal::StartsWith(stop, "elseif ")) {
            continue;
        }

        lines[outer_line] = internal::GetLuaLineIndent(lines[outer_line]) +
                            "if " + outer_condition + " and " +
                            inner_condition + " then";
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(inner_end));
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(inner_line));
        const std::size_t shifted_outer_end = outer_end - 2;
        lines[shifted_outer_end] =
            internal::GetLuaLineIndent(lines[shifted_outer_end]) + "else";
        const std::size_t shifted_tail_line = tail_line - 2;
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(shifted_tail_line + 1),
                     internal::GetLuaLineIndent(lines[shifted_outer_end]) + "end");
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool IsFastSimpleTruthyAndChain(std::string_view condition) {
    condition = internal::TrimWhitespace(condition);
    if (condition.empty() || condition.find(" or ") != std::string_view::npos ||
        condition.find('(') != std::string_view::npos ||
        condition.find(')') != std::string_view::npos ||
        condition.find('=') != std::string_view::npos ||
        condition.find('<') != std::string_view::npos ||
        condition.find('>') != std::string_view::npos ||
        condition.find('~') != std::string_view::npos) {
        return false;
    }

    constexpr std::string_view kAnd = " and ";
    std::size_t cursor = 0;
    while (cursor <= condition.size()) {
        const std::size_t next = condition.find(kAnd, cursor);
        const std::string_view part = internal::TrimWhitespace(
            next == std::string_view::npos
                ? condition.substr(cursor)
                : condition.substr(cursor, next - cursor));
        if (!IsFastBoundedHotspotSafeDottedName(part)) {
            return false;
        }
        if (next == std::string_view::npos) {
            break;
        }
        cursor = next + kAnd.size();
    }
    return true;
}

bool FoldFastBoundedHotspotNestedTruthGuardWithOuterElseToAnd(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    constexpr std::size_t kMaxThenBodyLines = 16;
    constexpr std::size_t kMaxElseBodyLines = 8;

    bool changed = false;
    for (std::size_t outer_line = 0; outer_line + 5 < lines.size(); ++outer_line) {
        const std::string outer_condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[outer_line])));
        if (!IsFastSimpleTruthyAndChain(outer_condition)) {
            continue;
        }

        const std::size_t inner_line = FastNextContentLine(lines, outer_line + 1);
        if (inner_line != outer_line + 1) {
            continue;
        }
        const std::string inner_condition = FastIfCondition(
            internal::TrimWhitespace(internal::StripLineComment(lines[inner_line])));
        if (!IsFastSimpleTruthyAndChain(inner_condition)) {
            continue;
        }

        std::size_t inner_end = std::string::npos;
        std::size_t outer_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, inner_line, &inner_end) ||
            !FindFastLuaMatchingEnd(lines, outer_line, &outer_end) ||
            FastLuaIfBlockHasSameLevelElse(lines, inner_line, inner_end) ||
            inner_end + 1 >= outer_end) {
            continue;
        }

        const std::size_t outer_else = FastNextContentLine(lines, inner_end + 1);
        if (outer_else != inner_end + 1 ||
            internal::TrimWhitespace(internal::StripLineComment(lines[outer_else])) !=
                "else") {
            continue;
        }
        const std::size_t else_body = FastNextContentLine(lines, outer_else + 1);
        if (else_body >= outer_end ||
            inner_end - inner_line - 1 > kMaxThenBodyLines ||
            outer_end - outer_else - 1 > kMaxElseBodyLines ||
            !FastLuaRangeContainsSafeCall(lines, inner_line + 1, inner_end)) {
            continue;
        }

        lines[outer_line] = internal::GetLuaLineIndent(lines[outer_line]) +
                            "if " + outer_condition + " and " +
                            inner_condition + " then";
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(inner_end));
        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(inner_line));
        changed = true;
        if (outer_line > 0) {
            --outer_line;
        }
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

bool ParseFastLevelLoadedCondition(std::string_view condition,
                                   bool* negated,
                                   std::string* argument) {
    if (negated == nullptr || argument == nullptr) {
        return false;
    }
    std::string text = FastTrimRedundantOuterParentheses(condition);
    text = std::string(internal::TrimWhitespace(text));
    bool is_negated = false;
    if (internal::StartsWith(text, "not ")) {
        is_negated = true;
        text = std::string(internal::TrimWhitespace(std::string_view(text).substr(4)));
    }
    constexpr std::string_view kPrefix = "IsLevelLoaded(";
    if (!internal::StartsWith(text, kPrefix) || text.back() != ')') {
        return false;
    }
    std::string_view arg = std::string_view(text).substr(
        kPrefix.size(),
        text.size() - kPrefix.size() - 1);
    arg = internal::TrimWhitespace(arg);
    if (arg.empty() || !IsFastBalancedLuaExpression(arg)) {
        return false;
    }
    *negated = is_negated;
    *argument = std::string(arg);
    return true;
}

bool FastNormalizedLineRangesEqual(const std::vector<std::string>& lines,
                                   std::size_t first_a,
                                   std::size_t last_a_exclusive,
                                   std::size_t first_b,
                                   std::size_t last_b_exclusive) {
    if (last_a_exclusive < first_a || last_b_exclusive < first_b ||
        (last_a_exclusive - first_a) != (last_b_exclusive - first_b)) {
        return false;
    }
    for (std::size_t offset = 0; offset < last_a_exclusive - first_a; ++offset) {
        if (internal::TrimWhitespace(internal::StripLineComment(lines[first_a + offset])) !=
            internal::TrimWhitespace(internal::StripLineComment(lines[first_b + offset]))) {
            return false;
        }
    }
    return true;
}

std::string FastLevelLoadedOrExpression(const std::array<std::string, 4>& args) {
    return "IsLevelLoaded(" + args[0] + ") or IsLevelLoaded(" + args[1] +
           ") or IsLevelLoaded(" + args[2] + ") or IsLevelLoaded(" + args[3] +
           ")";
}

bool TryFoldFastLevelLoadedPositiveOrChain(std::vector<std::string>* lines,
                                           std::size_t line_index) {
    if (lines == nullptr || line_index + 4 >= lines->size()) {
        return false;
    }
    std::array<bool, 4> negated{};
    std::array<std::string, 4> args{};
    for (std::size_t offset = 0; offset < 4; ++offset) {
        const std::string condition = FastIfCondition(internal::TrimWhitespace(
            internal::StripLineComment((*lines)[line_index + offset])));
        if (condition.empty() ||
            !ParseFastLevelLoadedCondition(condition, &negated[offset], &args[offset])) {
            return false;
        }
    }
    if (!negated[0] || !negated[1] || !negated[2] || negated[3]) {
        return false;
    }

    std::size_t outer_end = std::string::npos;
    std::size_t positive_end = std::string::npos;
    if (!FindFastLuaMatchingEnd(*lines, line_index, &outer_end) ||
        !FindFastLuaMatchingEnd(*lines, line_index + 3, &positive_end) ||
        positive_end + 3 != outer_end) {
        return false;
    }
    for (std::size_t end_line = positive_end + 1; end_line <= positive_end + 2;
         ++end_line) {
        if (internal::TrimWhitespace(internal::StripLineComment((*lines)[end_line])) !=
            "end") {
            return false;
        }
    }
    const std::size_t body_size = positive_end - (line_index + 4);
    const std::size_t duplicate_start = outer_end + 1;
    const std::size_t duplicate_end_exclusive = duplicate_start + body_size;
    if (body_size == 0 || duplicate_end_exclusive > lines->size()) {
        return false;
    }
    if (!FastNormalizedLineRangesEqual(*lines,
                                       line_index + 4,
                                       positive_end,
                                       duplicate_start,
                                       duplicate_end_exclusive) ||
        !FastLuaRangeContainsSafeCall(*lines, line_index + 4, positive_end)) {
        return false;
    }

    std::vector<std::string> replacement;
    replacement.push_back(internal::GetLuaLineIndent((*lines)[line_index]) + "if " +
                          FastLevelLoadedOrExpression(args) + " then");
    replacement.insert(replacement.end(),
                       lines->begin() + static_cast<std::ptrdiff_t>(line_index + 4),
                       lines->begin() + static_cast<std::ptrdiff_t>(positive_end));
    replacement.push_back(internal::GetLuaLineIndent((*lines)[line_index]) + "end");

    lines->erase(lines->begin() + static_cast<std::ptrdiff_t>(line_index),
                 lines->begin() + static_cast<std::ptrdiff_t>(duplicate_end_exclusive));
    lines->insert(lines->begin() + static_cast<std::ptrdiff_t>(line_index),
                  replacement.begin(),
                  replacement.end());
    return true;
}

bool TryFoldFastLevelLoadedNegativeOrElseChain(std::vector<std::string>* lines,
                                               std::size_t line_index) {
    if (lines == nullptr || line_index + 4 >= lines->size()) {
        return false;
    }
    std::array<bool, 4> negated{};
    std::array<std::string, 4> args{};
    for (std::size_t offset = 0; offset < 4; ++offset) {
        const std::string condition = FastIfCondition(internal::TrimWhitespace(
            internal::StripLineComment((*lines)[line_index + offset])));
        if (condition.empty() ||
            !ParseFastLevelLoadedCondition(condition, &negated[offset], &args[offset]) ||
            !negated[offset]) {
            return false;
        }
    }

    std::size_t outer_end = std::string::npos;
    std::size_t innermost_end = std::string::npos;
    if (!FindFastLuaMatchingEnd(*lines, line_index, &outer_end) ||
        !FindFastLuaMatchingEnd(*lines, line_index + 3, &innermost_end) ||
        innermost_end + 4 >= outer_end) {
        return false;
    }
    for (std::size_t end_line = innermost_end + 1; end_line <= innermost_end + 2;
         ++end_line) {
        if (internal::TrimWhitespace(internal::StripLineComment((*lines)[end_line])) !=
            "end") {
            return false;
        }
    }
    const std::size_t else_line = innermost_end + 3;
    if (internal::TrimWhitespace(internal::StripLineComment((*lines)[else_line])) !=
            "else" ||
        !FastLuaRangeContainsSafeCall(*lines, line_index + 4, innermost_end) ||
        !FastLuaRangeContainsSafeCall(*lines, else_line + 1, outer_end)) {
        return false;
    }

    std::vector<std::string> replacement;
    const std::string indent = internal::GetLuaLineIndent((*lines)[line_index]);
    replacement.push_back(indent + "if not (" + FastLevelLoadedOrExpression(args) +
                          ") then");
    replacement.insert(replacement.end(),
                       lines->begin() + static_cast<std::ptrdiff_t>(line_index + 4),
                       lines->begin() + static_cast<std::ptrdiff_t>(innermost_end));
    replacement.push_back(indent + "else");
    replacement.insert(replacement.end(),
                       lines->begin() + static_cast<std::ptrdiff_t>(else_line + 1),
                       lines->begin() + static_cast<std::ptrdiff_t>(outer_end));
    replacement.push_back(indent + "end");

    lines->erase(lines->begin() + static_cast<std::ptrdiff_t>(line_index),
                 lines->begin() + static_cast<std::ptrdiff_t>(outer_end + 1));
    lines->insert(lines->begin() + static_cast<std::ptrdiff_t>(line_index),
                  replacement.begin(),
                  replacement.end());
    return true;
}

bool FoldFastBoundedHotspotLevelLoadedOrChains(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);

    bool folded_positive = false;
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        if (TryFoldFastLevelLoadedPositiveOrChain(&lines, line_index)) {
            folded_positive = true;
            break;
        }
    }
    if (!folded_positive) {
        return false;
    }

    bool folded_negative = false;
    for (std::size_t line_index = 0; line_index < lines.size(); ++line_index) {
        if (TryFoldFastLevelLoadedNegativeOrElseChain(&lines, line_index)) {
            folded_negative = true;
            break;
        }
    }
    if (!folded_negative) {
        return false;
    }

    *source = internal::JoinLines(lines, had_trailing_newline);
    return true;
}

bool FoldFastBoundedHotspotNestedGuardElseToElseIf(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t outer_line = 0; outer_line + 6 < lines.size(); ++outer_line) {
        const std::string outer_condition = FastIfCondition(internal::TrimWhitespace(
            internal::StripLineComment(lines[outer_line])));
        constexpr std::string_view kNotPrefix = "not ";
        if (!internal::StartsWith(outer_condition, kNotPrefix)) {
            continue;
        }
        const std::string positive_outer = FastTrimRedundantOuterParentheses(
            internal::TrimWhitespace(std::string_view(outer_condition).substr(
                kNotPrefix.size())));
        if (positive_outer.empty()) {
            continue;
        }

        const std::size_t middle_line = FastNextContentLine(lines, outer_line + 1);
        const std::size_t inner_line = FastNextContentLine(lines, middle_line + 1);
        const std::size_t payload_line = FastNextContentLine(lines, inner_line + 1);
        if (middle_line != outer_line + 1 || inner_line != middle_line + 1 ||
            payload_line != inner_line + 1) {
            continue;
        }

        const std::string middle_condition = FastIfCondition(internal::TrimWhitespace(
            internal::StripLineComment(lines[middle_line])));
        const std::string inner_condition = FastIfCondition(internal::TrimWhitespace(
            internal::StripLineComment(lines[inner_line])));
        const std::string payload_condition = FastIfCondition(internal::TrimWhitespace(
            internal::StripLineComment(lines[payload_line])));
        if (middle_condition.empty() || inner_condition.empty() ||
            payload_condition.empty() ||
            payload_condition.find("IsLevelLoaded(") == std::string::npos ||
            !IsFastBalancedLuaExpression(middle_condition) ||
            !IsFastBalancedLuaExpression(inner_condition)) {
            continue;
        }

        std::size_t outer_end = std::string::npos;
        std::size_t middle_end = std::string::npos;
        std::size_t inner_end = std::string::npos;
        std::size_t payload_end = std::string::npos;
        if (!FindFastLuaMatchingEnd(lines, outer_line, &outer_end) ||
            !FindFastLuaMatchingEnd(lines, middle_line, &middle_end) ||
            !FindFastLuaMatchingEnd(lines, inner_line, &inner_end) ||
            !FindFastLuaMatchingEnd(lines, payload_line, &payload_end) ||
            payload_end + 1 > inner_end ||
            payload_end + 1 >= middle_end) {
            continue;
        }

        const std::size_t outer_else = middle_end + 1;
        if (outer_else >= outer_end ||
            internal::TrimWhitespace(internal::StripLineComment(lines[outer_else])) !=
            "else") {
            continue;
        }
        const std::size_t tail_if_line = FastNextContentLine(lines, outer_else + 1);
        if (tail_if_line != outer_else + 1) {
            continue;
        }
        const std::string tail_condition = FastTrimRedundantOuterParentheses(
            FastIfCondition(internal::TrimWhitespace(
                internal::StripLineComment(lines[tail_if_line]))));
        std::size_t tail_if_end = std::string::npos;
        if (tail_condition != positive_outer ||
            !FindFastLuaMatchingEnd(lines, tail_if_line, &tail_if_end) ||
            tail_if_end + 1 != outer_end ||
            !FastLuaRangeContainsSafeCall(lines, payload_line + 1, payload_end) ||
            !FastLuaRangeContainsSafeCall(lines, tail_if_line + 1, tail_if_end)) {
            continue;
        }

        std::vector<std::string> replacement;
        const std::string indent = internal::GetLuaLineIndent(lines[outer_line]);
        replacement.push_back(indent + "if " + outer_condition + " and " +
                              middle_condition + " and " + inner_condition + " then");
        replacement.insert(replacement.end(),
                           lines.begin() + static_cast<std::ptrdiff_t>(payload_line),
                           lines.begin() + static_cast<std::ptrdiff_t>(payload_end + 1));
        replacement.push_back(indent + "elseif " + positive_outer + " then");
        replacement.insert(replacement.end(),
                           lines.begin() + static_cast<std::ptrdiff_t>(tail_if_line + 1),
                           lines.begin() + static_cast<std::ptrdiff_t>(tail_if_end));
        replacement.push_back(indent + "end");

        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(outer_line),
                    lines.begin() + static_cast<std::ptrdiff_t>(outer_end + 1));
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(outer_line),
                     replacement.begin(),
                     replacement.end());
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

bool FoldFastBoundedHotspotTableAliasHandoffFields(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t local_line = 0; local_line + 2 < lines.size(); ++local_line) {
        std::string temp_name;
        std::string temp_rhs;
        bool temp_is_local = false;
        if (!ParseFastLuaAssignment(lines[local_line],
                                    &temp_name,
                                    &temp_rhs,
                                    &temp_is_local) ||
            !temp_is_local ||
            temp_rhs != "{}" ||
            !refii::lua::IsValidLuaIdentifier(temp_name) ||
            refii::lua::IsLuaKeyword(temp_name)) {
            continue;
        }

        std::size_t final_line = std::string::npos;
        std::string owner_lhs;
        for (std::size_t probe = local_line + 1;
             probe < lines.size() && probe <= local_line + 18;
             ++probe) {
            std::string lhs;
            std::string rhs;
            bool is_local = false;
            if (!ParseFastLuaAssignment(lines[probe], &lhs, &rhs, &is_local)) {
                continue;
            }
            if (!is_local && rhs == temp_name && lhs.find('.') != std::string::npos) {
                final_line = probe;
                owner_lhs = lhs;
                break;
            }
        }
        if (final_line == std::string::npos || owner_lhs.empty()) {
            continue;
        }

        const std::string owner_prefix = owner_lhs + ".";
        bool rewrote_owner_fields = false;
        bool unsafe_owner_reference = false;
        for (std::size_t line_index = local_line + 1; line_index < final_line;
             ++line_index) {
            std::string lhs;
            std::string rhs;
            bool is_local = false;
            const bool is_assignment =
                ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local);
            if (lines[line_index].find(owner_lhs) != std::string::npos &&
                (!is_assignment || is_local ||
                 !internal::StartsWith(lhs, owner_prefix))) {
                unsafe_owner_reference = true;
                break;
            }
            if (!is_assignment || is_local ||
                !internal::StartsWith(lhs, owner_prefix)) {
                continue;
            }
            lines[line_index] = internal::GetLuaLineIndent(lines[line_index]) +
                                temp_name +
                                lhs.substr(owner_lhs.size()) + " = " + rhs;
            rewrote_owner_fields = true;
        }
        if (unsafe_owner_reference || !rewrote_owner_fields) {
            continue;
        }

        std::unordered_set<std::string> initialized_children;
        for (std::size_t line_index = local_line + 1; line_index < final_line;
             ++line_index) {
            std::string lhs;
            std::string rhs;
            bool is_local = false;
            if (!ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) ||
                is_local) {
                continue;
            }
            const std::string temp_prefix = temp_name + ".";
            if (!internal::StartsWith(lhs, temp_prefix)) {
                continue;
            }
            const std::string_view suffix =
                std::string_view(lhs).substr(temp_prefix.size());
            if (suffix.find('.') == std::string_view::npos) {
                initialized_children.insert(lhs);
            }
        }

        for (std::size_t line_index = local_line + 1; line_index < final_line;
             ++line_index) {
            std::string lhs;
            std::string rhs;
            bool is_local = false;
            if (!ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) ||
                is_local) {
                continue;
            }
            const std::string temp_prefix = temp_name + ".";
            if (!internal::StartsWith(lhs, temp_prefix)) {
                continue;
            }
            const std::string_view suffix =
                std::string_view(lhs).substr(temp_prefix.size());
            const std::size_t dot = suffix.find('.');
            if (dot == std::string_view::npos) {
                continue;
            }
            const std::string child =
                temp_name + "." + std::string(suffix.substr(0, dot));
            if (!initialized_children.insert(child).second) {
                continue;
            }
            lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(line_index),
                         internal::GetLuaLineIndent(lines[line_index]) + child +
                             " = {}");
            ++line_index;
            ++final_line;
        }

        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

struct FastTableLiteralEntry {
    std::string key;
    std::string value;
    std::vector<std::pair<std::string, std::string>> children;
};

FastTableLiteralEntry* FindFastTableLiteralEntry(
    std::vector<FastTableLiteralEntry>* entries,
    std::string_view key) {
    if (entries == nullptr) {
        return nullptr;
    }
    for (FastTableLiteralEntry& entry : *entries) {
        if (entry.key == key) {
            return &entry;
        }
    }
    return nullptr;
}

bool FoldFastBoundedHotspotTableAliasHandoffLiteral(std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    for (std::size_t local_line = 0; local_line + 2 < lines.size(); ++local_line) {
        std::string temp_name;
        std::string temp_rhs;
        bool temp_is_local = false;
        if (!ParseFastLuaAssignment(lines[local_line],
                                    &temp_name,
                                    &temp_rhs,
                                    &temp_is_local) ||
            !temp_is_local || temp_rhs != "{}" ||
            !refii::lua::IsValidLuaIdentifier(temp_name) ||
            refii::lua::IsLuaKeyword(temp_name)) {
            continue;
        }

        std::size_t final_line = std::string::npos;
        std::string owner_lhs;
        std::vector<FastTableLiteralEntry> entries;
        bool unsafe = false;
        for (std::size_t line_index = local_line + 1;
             line_index < lines.size() && line_index <= local_line + 18;
             ++line_index) {
            std::string lhs;
            std::string rhs;
            bool is_local = false;
            if (!ParseFastLuaAssignment(lines[line_index], &lhs, &rhs, &is_local) ||
                is_local) {
                unsafe = true;
                break;
            }
            if (rhs == temp_name && lhs.find('.') != std::string::npos) {
                final_line = line_index;
                owner_lhs = lhs;
                break;
            }

            const std::string temp_prefix = temp_name + ".";
            if (!internal::StartsWith(lhs, temp_prefix)) {
                unsafe = true;
                break;
            }
            const std::string suffix = lhs.substr(temp_prefix.size());
            const std::size_t dot = suffix.find('.');
            if (dot == std::string::npos) {
                if (!refii::lua::IsValidLuaIdentifier(suffix) ||
                    refii::lua::IsLuaKeyword(suffix)) {
                    unsafe = true;
                    break;
                }
                entries.push_back({suffix, rhs, {}});
                continue;
            }

            const std::string child = suffix.substr(0, dot);
            const std::string child_key = suffix.substr(dot + 1);
            if (!refii::lua::IsValidLuaIdentifier(child) ||
                refii::lua::IsLuaKeyword(child) ||
                !refii::lua::IsValidLuaIdentifier(child_key) ||
                refii::lua::IsLuaKeyword(child_key)) {
                unsafe = true;
                break;
            }
            FastTableLiteralEntry* entry = FindFastTableLiteralEntry(&entries, child);
            if (entry == nullptr || entry->value != "{}") {
                unsafe = true;
                break;
            }
            entry->children.emplace_back(child_key, rhs);
        }
        if (unsafe || final_line == std::string::npos || entries.empty() ||
            owner_lhs.empty()) {
            continue;
        }

        std::vector<std::string> replacement;
        const std::string indent = internal::GetLuaLineIndent(lines[local_line]);
        replacement.push_back(indent + owner_lhs + " = {");
        for (std::size_t entry_index = 0; entry_index < entries.size(); ++entry_index) {
            const FastTableLiteralEntry& entry = entries[entry_index];
            const bool last_entry = entry_index + 1 == entries.size();
            if (entry.value == "{}" && !entry.children.empty()) {
                replacement.push_back(indent + entry.key + " = {");
                for (std::size_t child_index = 0; child_index < entry.children.size();
                     ++child_index) {
                    const auto& [child_key, child_value] = entry.children[child_index];
                    const bool last_child = child_index + 1 == entry.children.size();
                    replacement.push_back(indent + child_key + " = " + child_value +
                                          (last_child ? "" : ","));
                }
                replacement.push_back(indent + "}" + (last_entry ? "" : ","));
            } else {
                replacement.push_back(indent + entry.key + " = " + entry.value +
                                      (last_entry ? "" : ","));
            }
        }
        replacement.push_back(indent + "}");

        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(local_line),
                    lines.begin() + static_cast<std::ptrdiff_t>(final_line + 1));
        lines.insert(lines.begin() + static_cast<std::ptrdiff_t>(local_line),
                     replacement.begin(),
                     replacement.end());
        *source = internal::JoinLines(lines, had_trailing_newline);
        return true;
    }

    return false;
}

