bool RemoveFastBoundedHotspotOverwrittenLocalConstructorReseeds(
    std::string* source) {
    if (source == nullptr || source->empty()) {
        return false;
    }

    bool had_trailing_newline = false;
    std::vector<std::string> lines =
        internal::SplitLines(*source, &had_trailing_newline);
    bool changed = false;
    for (std::size_t line_index = 0; line_index + 1 < lines.size(); ++line_index) {
        std::string initial_lhs;
        std::string initial_rhs;
        bool initial_is_local = false;
        if (!ParseFastLuaAssignment(lines[line_index],
                                    &initial_lhs,
                                    &initial_rhs,
                                    &initial_is_local) ||
            !initial_is_local || !refii::lua::IsValidLuaIdentifier(initial_lhs) ||
            !IsFastBoundedHotspotConstructorCall(initial_rhs)) {
            continue;
        }

        bool saw_field_patch = false;
        std::size_t reseed_line = std::string::npos;
        for (std::size_t scan = line_index + 1; scan < lines.size(); ++scan) {
            const std::string_view trimmed =
                internal::TrimWhitespace(internal::StripLineComment(lines[scan]));
            if (trimmed.empty()) {
                continue;
            }
            if (internal::StartsWith(trimmed, "function ") ||
                internal::StartsWith(trimmed, "local function ") ||
                trimmed == "end") {
                break;
            }

            std::string lhs;
            std::string rhs;
            bool is_local = false;
            if (!ParseFastLuaAssignment(lines[scan], &lhs, &rhs, &is_local)) {
                if (saw_field_patch) {
                    break;
                }
                continue;
            }
            if (!is_local &&
                (internal::StartsWith(lhs, initial_lhs + ".") ||
                 internal::StartsWith(lhs, initial_lhs + "["))) {
                saw_field_patch = true;
                continue;
            }
            if (!is_local && lhs == initial_lhs && rhs == initial_rhs &&
                saw_field_patch) {
                reseed_line = scan;
                break;
            }
            if (is_local || lhs == initial_lhs) {
                break;
            }
        }
        if (reseed_line == std::string::npos) {
            continue;
        }

        lines.erase(lines.begin() + static_cast<std::ptrdiff_t>(reseed_line));
        changed = true;
    }

    if (changed) {
        *source = internal::JoinLines(lines, had_trailing_newline);
    }
    return changed;
}

